import { Fund, FundHistoryPoint } from '../types';

interface EastmoneyResponse {
  fundcode: string;
  name: string;
  jzrq: string; // Date of dwjz (Previous close date)
  dwjz: string; // Net Value (Previous Close)
  gsz: string;  // Estimated Value (Real-time)
  gszzl: string; // Growth Rate %
  gztime: string; // Update Time
}

// Helper to fetch data via JSONP because Eastmoney doesn't support CORS for direct Fetch calls
const fetchJsonp = (url: string): Promise<EastmoneyResponse> => {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    const callbackName = 'jsonpgz';

    // Define global callback
    (window as any)[callbackName] = (data: EastmoneyResponse) => {
      resolve(data);
      // Cleanup
      delete (window as any)[callbackName];
      document.body.removeChild(script);
    };

    script.src = url;
    script.onerror = () => {
      reject(new Error(`Failed to load fund data from ${url}`));
      delete (window as any)[callbackName];
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
    };

    document.body.appendChild(script);
  });
};

export const fetchFundRealtime = async (code: string): Promise<Fund> => {
  try {
    // Timestamp to prevent caching
    const timestamp = new Date().getTime();
    const url = `https://fundgz.1234567.com.cn/js/${code}.js?rt=${timestamp}`;

    const data = await fetchJsonp(url);

    return {
      code: data.fundcode,
      name: data.name,
      netValue: parseFloat(data.dwjz),
      estimatedValue: parseFloat(data.gsz),
      growthRate: parseFloat(data.gszzl),
      updateTime: data.gztime.split(' ')[1] || data.gztime, // Extract HH:MM
      tags: ['实盘'], // Real data tags
    };
  } catch (error) {
    console.error(`Error fetching fund ${code}:`, error);
    throw error;
  }
};

// Since we cannot get real minute-level intraday ticks easily without a complex backend,
// We generate a "Truthful Trend" line: Start at PrevClose (9:30), End at Current Estimate (Now).
export const generateTrendData = (fund: Fund): FundHistoryPoint[] => {
  const points: FundHistoryPoint[] = [];

  // Start Point (9:30 AM) - Value is Previous Close (netValue)
  points.push({
    time: '09:30',
    value: fund.netValue
  });

  // End Point (Current Time) - Value is Estimated Value
  // If market is closed (after 15:00), cap at 15:00
  const now = new Date();
  const isAfterClose = now.getHours() >= 15;
  const currentTimeStr = isAfterClose ? '15:00' : fund.updateTime;

  points.push({
    time: currentTimeStr,
    value: fund.estimatedValue
  });

  return points;
};

import React, { useState } from 'react';
import { X, Search, CheckCircle, PieChart, DollarSign } from 'lucide-react';
