interface AddFundModalProps {
  onClose: () => void;
  onAdd: (code: string, amount: number, cost: number) => Promise<void>;
  existingCodes: string[];
}

const AddFundModal: React.FC<AddFundModalProps> = ({ onClose, onAdd, existingCodes }) => {
  const [code, setCode] = useState('');
  const [amount, setAmount] = useState('');
  const [cost, setCost] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [previewName, setPreviewName] = useState('');

  const handleCodeBlur = async () => {
    if (code.length === 6 && !existingCodes.includes(code)) {
      setIsLoading(true);
      setError('');
      try {
        const fund = await fetchFundRealtime(code);
        setPreviewName(fund.name);
        // Auto-fill cost with current net value if empty
        if (!cost) setCost(fund.netValue.toString());
      } catch (err) {
        setError('无法获取该基金信息，请检查代码');
        setPreviewName('');
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (code.length < 6) {
      setError('请输入正确的6位基金代码');
      return;
    }

    if (existingCodes.includes(code)) {
      setError('该基金已在您的列表中');
      return;
    }

    setIsLoading(true);
    try {
      await onAdd(code, parseFloat(amount) || 0, parseFloat(cost) || 0);
      onClose();
    } catch (err) {
      setError('添加失败，请重试');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white dark:bg-gray-800 rounded-2xl w-full max-w-md shadow-2xl scale-100 transform transition-all">
