import React, { useState } from 'react';
import { X, Search, CheckCircle, PieChart } from 'lucide-react';
import { fetchFundRealtime } from '../services/fundService';

interface AddFundModalProps {
  onClose: () => void;
  onAdd: (code: string, amount: number, cost: number) => Promise<void>;
  existingCodes: string[];
}

const AddFundModal: React.FC<AddFundModalProps> = ({ onClose, onAdd, existingCodes }) => {
  const [code, setCode] = useState('');
  const [amount, setAmount] = useState('');
  const [totalAmount, setTotalAmount] = useState(''); // User inputs Total RMB, not Unit Cost
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [previewName, setPreviewName] = useState('');

  const handleCodeBlur = async () => {
    if (code.length === 6 && !existingCodes.includes(code)) {
      setIsLoading(true);
      setError('');
      try {
        const fund = await fetchFundRealtime(code);
        setPreviewName(fund.name);
      } catch (err) {
        setError('无法获取该基金信息，请检查代码');
        setPreviewName('');
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (code.length < 6) {
      setError('请输入正确的6位基金代码');
      return;
    }

    if (existingCodes.includes(code)) {
      setError('该基金已在您的列表中');
