import { Fund, FundHistoryPoint } from '../types';

interface EastmoneyResponse {
  fundcode: string;
  name: string;
  jzrq: string; // Date of dwjz
  dwjz: string; // Net Value (Previous Close)
  gsz: string;  // Estimated Value (Real-time)
  gszzl: string; // Growth Rate %
  gztime: string; // Update Time
}

// Global Callback Registry
const CALLBACK_NAME = 'jsonpgz';
// Store pending requests: key is fund code
const pendingRequests = new Map<string, { resolve: (data: EastmoneyResponse) => void; reject: (err: Error) => void; timer: number }>();

// Initialize the global callback function ONLY ONCE.
// This function dispatches the data to the correct promise based on fundcode.
if (typeof window !== 'undefined' && !(window as any)[CALLBACK_NAME]) {
  (window as any)[CALLBACK_NAME] = (data: EastmoneyResponse) => {
    const code = data.fundcode;
    const request = pendingRequests.get(code);

    // If we have a pending request for this code, resolve it
    if (request) {
      clearTimeout(request.timer);
      request.resolve(data);
      pendingRequests.delete(code);
    }
    // If not, it might be a stale request or duplicate, we just ignore it.
  };
}

const fetchJsonp = (code: string): Promise<EastmoneyResponse> => {
  return new Promise((resolve, reject) => {
    // If a request is already pending for this code, cancel the previous one to avoid race conditions
    if (pendingRequests.has(code)) {
      const prev = pendingRequests.get(code);
      if (prev) {
        clearTimeout(prev.timer);
        prev.reject(new Error('Request cancelled by new request'));
      }
    }

    const timestamp = new Date().getTime();
    const url = `https://fundgz.1234567.com.cn/js/${code}.js?rt=${timestamp}`;
    const scriptId = `fund-script-${code}`;

    // Cleanup existing script tag if any (though usually we remove them on load/error)
    const existingScript = document.getElementById(scriptId);
    if (existingScript) document.body.removeChild(existingScript);

    // Set a timeout to prevent hanging promises
    const timer = window.setTimeout(() => {
        if (pendingRequests.has(code)) {
            pendingRequests.delete(code);
            reject(new Error(`请求超时: ${code}`));
            const s = document.getElementById(scriptId);
            if (s) document.body.removeChild(s);
        }
    }, 5000); // 5 seconds timeout

    // Register the request
    pendingRequests.set(code, { resolve, reject, timer });

    const script = document.createElement('script');
    script.src = url;
    script.id = scriptId;

    // Handle loading errors (404, network error, CORS block appearing as error)
    script.onerror = () => {
      if (pendingRequests.has(code)) {
        clearTimeout(timer);
        pendingRequests.delete(code);
        // Note: Specific HTTP status codes (like 404) are not available in script.onerror
        reject(new Error(`无法加载基金数据 (Code: ${code})，请检查代码或网络。`));
      }
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
    };

    // Script execution finishes
    script.onload = () => {
      // The script executes the global callback synchronously.
      // We clean up the script tag here.
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
    };

    document.body.appendChild(script);
  });
};

export const fetchFundRealtime = async (code: string): Promise<Fund> => {
  try {
    const data = await fetchJsonp(code);

    // Parse values, handle potential empty strings
    const netValue = parseFloat(data.dwjz || '0');
    const estimatedValue = parseFloat(data.gsz || '0');
    const growthRate = parseFloat(data.gszzl || '0');

    // Simple logic to guess tags based on name (since API doesn't return tags)
    const tags = ['混合型'];
    if (data.name.includes('酒')) tags.push('消费');
    if (data.name.includes('医') || data.name.includes('药')) tags.push('医药');
    if (data.name.includes('新能') || data.name.includes('光伏')) tags.push('新能源');
    if (data.name.includes('半导体') || data.name.includes('电子') || data.name.includes('信息')) tags.push('科技');
    if (data.name.includes('蓝筹')) tags.push('蓝筹');
    if (data.name.includes('红利')) tags.push('红利');
    if (data.name.includes('沪深') || data.name.includes('指数') || data.name.includes('ETF')) {
        tags[0] = '指数型';
    } else if (data.name.includes('债')) {
        tags[0] = '债券型';
    }

    return {
      code: data.fundcode,
      name: data.name,
      netValue,
      // If estimated value is missing or 0 (sometimes happens on weekends/holidays), fallback to netValue
      estimatedValue: (isNaN(estimatedValue) || estimatedValue === 0) ? netValue : estimatedValue, 
      growthRate: isNaN(growthRate) ? 0 : growthRate,
      updateTime: data.gztime || '--:--',
      tags
    };
  } catch (error) {
    console.warn(`Error fetching fund ${code}:`, error);
    throw error;
  }
};

export const generateTrendData = (fund: Fund): FundHistoryPoint[] => {
    const data: FundHistoryPoint[] = [];

    // Point 1: Previous Close (treated as 09:30 baseline)
    data.push({ time: '09:30', value: fund.netValue });

    // Point 2: Current Estimate
    const now = new Date();
    const currentHour = now.getHours();
    const currentMin = now.getMinutes();

    let endTimeStr = `${currentHour.toString().padStart(2, '0')}:${currentMin.toString().padStart(2, '0')}`;

    // Clamp time to trading hours for display
    if (currentHour < 9 || (currentHour === 9 && currentMin < 30)) {
        endTimeStr = '09:30'; 
    } else if (currentHour >= 15) {
        endTimeStr = '15:00';
    }

    // Avoid duplicate points if market just opened
    if (endTimeStr !== '09:30') {
         data.push({ time: endTimeStr, value: fund.estimatedValue });
    } else {
        // Just to show a line, add a tiny offset point
        data.push({ time: '09:31', value: fund.estimatedValue });
    }

    return data;
};

import React, { useState, useEffect } from 'react';
import { fetchFundRealtime } from './services/fundService';
