const App: React.FC = () => {
  const [funds, setFunds] = useState<Fund[]>([]);
  const [holdings, setHoldings] = useState<Record<string, Holding>>({});
  const [selectedFundCode, setSelectedFundCode] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isAutoRefresh, setIsAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [lastUpdated, setLastUpdated] = useState<string>('');

  // Initial Load (Empty initially, user adds funds)
  useEffect(() => {
    // In a real app, load from localStorage here
    const savedCodes = ['005827', '012414']; // Default example funds
    const savedHoldings = {
        '005827': { fundCode: '005827', amount: 1000, cost: 2.100 },
        '012414': { fundCode: '012414', amount: 5000, cost: 0.950 },
    };
    setHoldings(savedHoldings);
    refreshFunds(savedCodes);
  }, []);

  const refreshFunds = async (codesToFetch?: string[]) => {
    // Use passed codes OR current funds state. 
    // If using current state, map to codes.
    const codes = codesToFetch || funds.map(f => f.code);

    if (codes.length === 0) return;

    // We process requests individually so one failure doesn't break the whole batch
    const results: Fund[] = [];

    await Promise.all(codes.map(async (code) => {
        try {
            const fund = await fetchFundRealtime(code);
            results.push(fund);
        } catch (e) {
            // Keep existing data if fetch fails
            const existing = funds.find(f => f.code === code);
            if (existing) {
                results.push(existing);
            }
            // If it's a new fund being added and fails, it won't be in 'existing', so it won't be added.
            // This is handled by AddFundModal catching the error.
        }
    }));

    if (results.length > 0) {
        setFunds(prev => {
             // Create a map of new results for easy lookup
             const resultMap = new Map(results.map(f => [f.code, f]));

             // If we are refreshing specific codes (initial load), we just use results.
             // If we are auto-refreshing, we want to update existing items in place or append?
             // Safest is to rebuild the list based on current funds + updates.

             if (codesToFetch) {
                 return results;
             }

             // For auto-refresh, map over previous to maintain order, updating where possible
             return prev.map(f => resultMap.get(f.code) || f);
        });

        const now = new Date();
        setLastUpdated(`${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`);
    }
  };

  // Real-time Polling Loop (Every 60s for real data)
  useEffect(() => {
    if (!isAutoRefresh) return;

    const intervalId = setInterval(() => {
      refreshFunds();
    }, 60000); // 60 seconds

    return () => clearInterval(intervalId);
  }, [isAutoRefresh, funds.length]); // Re-create interval if funds list changes

  const handleUpdateHolding = (amount: number, cost: number) => {
    if (!selectedFundCode) return;
    setHoldings(prev => ({
      ...prev,
      [selectedFundCode]: { fundCode: selectedFundCode, amount, cost }
    }));
  };

  const handleAddFund = async (code: string, amount: number, cost: number) => {
    try {
        const newFund = await fetchFundRealtime(code);
        setFunds(prev => {
            // Avoid duplicates
            if(prev.find(f => f.code === code)) return prev;
            return [newFund, ...prev];
        });

        if (amount > 0) {
            setHoldings(prev => ({
                ...prev,
                [code]: { fundCode: code, amount, cost }
            }));
        }

        setIsAddModalOpen(false);
    } catch (e) {
        console.error("Error adding fund", e);
        throw e; // Let modal handle error display
    }
