                    基金智投 AI
                </h1>
                <span className="text-xs text-gray-400 mt-1">实盘估值监控</span>
              </div>
            </div>

            {/* Market Status Indicator */}
            <div className={`hidden md:flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-medium ${marketStatus.color}`}>
                <div className={`w-1.5 h-1.5 rounded-full ${marketStatus.active ? 'bg-green-500 animate-pulse' : 'bg-gray-400'}`}></div>
                <Clock className="w-3 h-3" />
                {marketStatus.text}
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
              {/* Auto Refresh Toggle */}
              <button
                onClick={() => setIsAutoRefresh(!isAutoRefresh)}
