                    refreshFunds();
                }}
                className={`p-2 rounded-full transition-colors bg-gray-100 text-gray-500 hover:bg-blue-100 hover:text-blue-600 dark:bg-gray-800 dark:hover:bg-blue-900/30 dark:hover:text-blue-400`}
                title="刷新数据"
              >
                <RefreshCw className={`w-5 h-5`} />
