                        <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                                className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                                title="查看详情"
                            >
                                <Eye className="w-4 h-4" />
                            </button>
                            <button 
                                className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                                onClick={(e) => handleDeleteClick(e, fund.code)}
                                title="删除基金"
                            >
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {filteredFunds.length === 0 && (
            <div className="p-12 text-center text-gray-400">
                {funds.length === 0 ? "暂无自选基金，请点击添加" : "未找到匹配的基金。"}
            </div>
          )}
        </div>
      </main>

      <FundDetailModal 
        fund={selectedFund} 
        onClose={() => setSelectedFundCode(null)} 
        holding={selectedFundCode ? holdings[selectedFundCode] : undefined}
        onUpdateHolding={handleUpdateHolding}
        onDelete={() => selectedFundCode && executeDelete(selectedFundCode)}
      />

      {isAddModalOpen && (
        <AddFundModal 
          onClose={() => setIsAddModalOpen(false)}
          onAdd={handleAddFund}
          existingCodes={funds.map(f => f.code)}
        />
      )}
    </div>
  );
};

export default App;

export interface Fund {
  code: string;
  name: string;
  netValue: number; // Previous close NAV
  estimatedValue: number; // Real-time estimated NAV
  growthRate: number; // Percentage change
  updateTime: string;
  tags: string[];
  status?: 'ok' | 'loading' | 'error';
}

export interface FundHistoryPoint {
  time: string;
  value: number;
}

export interface Holding {
  fundCode: string;
  amount: number; // Number of shares held
  cost: number; // Average cost per share
}

export interface AIAnalysisResult {
  sentiment: 'positive' | 'neutral' | 'negative';
  analysis: string;
}

export enum MarketStatus {
  OPEN = 'Trading',
  CLOSED = 'Closed',
  PRE_MARKET = 'Pre-Market',
}

import React, { useState, useEffect, useRef } from 'react';
import { fetchFundRealtime } from './services/fundService';
import { Fund, Holding } from './types';
import FundDetailModal from './components/FundDetailModal';
import AddFundModal from './components/AddFundModal';
import { Search, Plus, TrendingUp, RefreshCw, Eye, Wallet, Trash2, Clock, PlayCircle, PauseCircle, AlertCircle } from 'lucide-react';

const getMarketStatus = () => {
  const now = new Date();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const time = hour * 60 + minute;

  // Weekend
  if (day === 0 || day === 6) return { text: '休市中', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };

  // 9:15 - 9:30 Pre-market
  if (time >= 9 * 60 + 15 && time < 9 * 60 + 30) {
      return { text: '盘前交易', color: 'bg-orange-50 text-orange-600 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800' };
  }
  // 9:30 - 11:30 Open
  if (time >= 9 * 60 + 30 && time < 11 * 60 + 30) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }
  // 11:30 - 13:00 Break
  if (time >= 11 * 60 + 30 && time < 13 * 60) {
      return { text: '午间休市', color: 'bg-gray-50 text-gray-600 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
  }
  // 13:00 - 15:00 Open
  if (time >= 13 * 60 && time < 15 * 60) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }

  return { text: '已收盘', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
};

const SkeletonRow = () => (
  <tr className="animate-pulse border-b border-gray-100 dark:border-gray-700">
    <td className="px-6 py-4">
      <div className="flex flex-col gap-2">
        <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-32"></div>
        <div className="h-3 bg-gray-100 dark:bg-gray-800 rounded w-16"></div>
      </div>
    </td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-16 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-12 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-20 ml-auto"></div></td>
    <td className="px-6 py-4 text-center"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-8 mx-auto"></div></td>
  </tr>
);

const App: React.FC = () => {
  const [funds, setFunds] = useState<Fund[]>([]);
  const [holdings, setHoldings] = useState<Record<string, Holding>>({});
  const [selectedFundCode, setSelectedFundCode] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isAutoRefresh, setIsAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [lastUpdated, setLastUpdated] = useState<string>('');
  const [marketStatus, setMarketStatus] = useState(getMarketStatus());

  // Loading States
  const [isAppLoading, setIsAppLoading] = useState(true); // Initial load
  const [isRefreshing, setIsRefreshing] = useState(false); // Manual/Auto refresh

  // Refs for checking current state inside async functions
  const fundsRef = useRef<Fund[]>([]);

  // Keep ref in sync
  useEffect(() => {
    fundsRef.current = funds;
  }, [funds]);

  // Initial Load with Persistence
  useEffect(() => {
    const init = async () => {
      // Load codes and holdings from LocalStorage
      const savedCodesStr = localStorage.getItem('fund_codes');
      const savedHoldingsStr = localStorage.getItem('fund_holdings');

      let codesToFetch: string[] = [];

      // Parse Holdings
      if (savedHoldingsStr) {
          try {
              setHoldings(JSON.parse(savedHoldingsStr));
          } catch (e) {
              console.error('Failed to parse saved holdings', e);
          }
      }

      // Parse Codes
      if (savedCodesStr) {
          try {
              const parsed = JSON.parse(savedCodesStr);
              if (Array.isArray(parsed) && parsed.length > 0) {
                  codesToFetch = parsed;
              }
          } catch (e) {
              console.error('Failed to parse saved codes', e);
          }
      } else {
          // Default data for new users
          codesToFetch = ['005827', '012414'];
          setHoldings({
              '005827': { fundCode: '005827', amount: 1000, cost: 2.100 },
              '012414': { fundCode: '012414', amount: 5000, cost: 0.950 },
          });
      }

      // Initial Fetch
      if (codesToFetch.length > 0) {
        await refreshFunds(codesToFetch, true);
      } else {
        setFunds([]);
      }

      setIsAppLoading(false);
    };

    init();

    // Market Status Timer
    const timer = setInterval(() => setMarketStatus(getMarketStatus()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Persistence: Save when changed
  // Note: We use isAppLoading to prevent saving empty states during initialization
  useEffect(() => {
    if (!isAppLoading) {
        const codes = funds.map(f => f.code);
        localStorage.setItem('fund_codes', JSON.stringify(codes));
    }
  }, [funds, isAppLoading]);

  useEffect(() => {
    if (!isAppLoading) {
        localStorage.setItem('fund_holdings', JSON.stringify(holdings));
    }
  }, [holdings, isAppLoading]);

  // Core Refresh Logic
  const refreshFunds = async (specificCodes?: string[], isInitial: boolean = false) => {
    if (!isInitial) setIsRefreshing(true);

    // Determine which codes to fetch. 
    // If specificCodes provided (e.g. Init), use them.
    // Otherwise use current funds from Ref to ensure we don't use stale closure data.
    const codesToFetch = specificCodes || fundsRef.current.map(f => f.code);

    if (codesToFetch.length === 0) {
        if (specificCodes) setFunds([]);
        if (!isInitial) setIsRefreshing(false);
        return;
    }

    const results = await Promise.all(codesToFetch.map(async (code) => {
        try {
            const fund = await fetchFundRealtime(code);
            return { ...fund, status: 'ok' as const };
        } catch (e) {
            // If fetching fails, we try to find the existing data to preserve it
            // or return an error placeholder
            const existing = fundsRef.current.find(f => f.code === code);
            if (existing) {
                return { ...existing, status: 'error' as const };
            }
            return { 
                code, 
                name: '加载失败', 
                netValue: 0, 
                estimatedValue: 0, 
                growthRate: 0, 
                updateTime: '--:--', 
                tags: [], 
                status: 'error' as const 
            };
        }
    }));

    // State Update Logic to handle Race Conditions (like Deletion during refresh)
    setFunds(prevFunds => {
         // If this was an explicit load (Init or Add), we trust the results
         if (specificCodes) {
             return results;
         }

         // For auto-refresh, we only update funds that STILL exist in the state.
         // This prevents a deleted fund from reappearing if the network request finishes after deletion.
         return prevFunds.map(prevFund => {
             const newData = results.find(r => r.code === prevFund.code);
             return newData || prevFund;
         });
    });

    const now = new Date();
    setLastUpdated(`${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`);

    if (!isInitial) setIsRefreshing(false);
  };

  // Auto-Refresh Loop
  useEffect(() => {
    if (!isAutoRefresh || isAppLoading) return;
    const intervalId = setInterval(() => {
      refreshFunds();
    }, 60000); 
    return () => clearInterval(intervalId);
  }, [isAutoRefresh, isAppLoading]); // No need to depend on funds, refreshFunds reads from ref

  const handleUpdateHolding = (amount: number, cost: number) => {
    if (!selectedFundCode) return;
    setHoldings(prev => ({
      ...prev,
      [selectedFundCode]: { fundCode: selectedFundCode, amount, cost }
    }));
  };

  const handleAddFund = async (code: string, amount: number, cost: number) => {
    try {
        const newFund = await fetchFundRealtime(code);
        setFunds(prev => {
            if(prev.find(f => f.code === code)) return prev;
            return [{ ...newFund, status: 'ok' }, ...prev];
        });

        if (amount > 0 || cost > 0) {
            setHoldings(prev => ({
                ...prev,
                [code]: { fundCode: code, amount, cost }
            }));
        }

        setIsAddModalOpen(false);
    } catch (e) {
        console.error("Error adding fund", e);
        throw e;
    }
  };

  const executeDelete = (code: string) => {
      if (confirm('确定要删除这个基金吗？')) {
          // 1. Remove from State immediately
          setFunds(prev => prev.filter(f => f.code !== code));
          setHoldings(prev => {
              const next = { ...prev };
              delete next[code];
              return next;
          });

          if (selectedFundCode === code) {
              setSelectedFundCode(null);
          }

          // 2. Force update LocalStorage immediately (Safety net)
          // (Though useEffect will also catch this, explicit set ensures sync if tab closes fast)
          const currentCodes = funds.filter(f => f.code !== code).map(f => f.code);
          localStorage.setItem('fund_codes', JSON.stringify(currentCodes));
      }
  };

  const handleDeleteClick = (e: React.MouseEvent, code: string) => {
      e.stopPropagation();
      executeDelete(code);
  };

  const selectedFund = funds.find(f => f.code === selectedFundCode) || null;
  const holdingsValues = Object.values(holdings) as Holding[];

  // Stats Calculations
  const totalAssets = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    return sum + (fund ? fund.estimatedValue * holding.amount : 0);
  }, 0);

  const dayProfit = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    if (!fund) return sum;
    return sum + (holding.amount * (fund.estimatedValue - fund.netValue));
  }, 0);

  const totalReturn = holdingsValues.reduce<number>((sum, holding) => {
      const fund = funds.find(f => f.code === holding.fundCode);
      if (!fund) return sum;
      return sum + ((fund.estimatedValue * holding.amount) - (holding.amount * holding.cost));
  }, 0);

  const filteredFunds = funds.filter(f => 
    f.name.includes(searchTerm) || f.code.includes(searchTerm)
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 font-sans">
      {/* Navbar */}
      <nav className="sticky top-0 z-30 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-gray-200 dark:border-gray-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg">
                <TrendingUp className="w-6 h-6 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600 dark:from-blue-400 dark:to-indigo-400 leading-none">
                    基金智投 AI
                </h1>
                <span className="text-xs text-gray-400 mt-1">实盘估值监控</span>
              </div>
            </div>

            {/* Market Status Indicator */}
            <div className={`hidden md:flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-medium ${marketStatus.color}`}>
                <div className={`w-1.5 h-1.5 rounded-full ${marketStatus.active ? 'bg-green-500 animate-pulse' : 'bg-gray-400'}`}></div>
                <Clock className="w-3 h-3" />
                {marketStatus.text}
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
              {/* Auto Refresh Toggle */}
              <button
                onClick={() => setIsAutoRefresh(!isAutoRefresh)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                  isAutoRefresh 
                    ? 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' 
                    : 'bg-gray-50 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700'
                }`}
                title={isAutoRefresh ? "点击暂停自动刷新" : "点击开启自动刷新"}
              >
                {isAutoRefresh ? <PauseCircle className="w-3.5 h-3.5" /> : <PlayCircle className="w-3.5 h-3.5" />}
                <span className="hidden sm:inline">{isAutoRefresh ? '自动刷新' : '已暂停'}</span>
              </button>

              <div className="hidden sm:block text-xs text-gray-400 text-right">
                  <div>更新: {lastUpdated}</div>
                  <div className="md:hidden text-[10px]">{marketStatus.text}</div>
              </div>
              <button 
                onClick={() => {
                    refreshFunds();
                }}
                disabled={isRefreshing}
                className={`p-2 rounded-full transition-all bg-gray-100 text-gray-500 hover:bg-blue-100 hover:text-blue-600 dark:bg-gray-800 dark:hover:bg-blue-900/30 dark:hover:text-blue-400 ${isRefreshing ? 'animate-spin text-blue-600 bg-blue-50' : ''}`}
                title="刷新数据"
              >
                <RefreshCw className={`w-5 h-5`} />
              </button>
              <div className="h-8 w-8 rounded-full bg-gradient-to-tr from-blue-500 to-purple-500"></div>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Dashboard Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className="absolute right-0 top-0 w-32 h-32 bg-blue-500/10 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <Wallet className="w-5 h-5" />
                    <span className="text-sm font-medium">总资产</span>
                </div>
                <div className="text-3xl font-bold text-gray-900 dark:text-white">
                    {isAppLoading ? (
                         <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `¥${totalAssets.toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                 <div className="text-sm text-gray-400 mt-1">
                    总盈亏: <span className={totalReturn >= 0 ? 'text-red-500' : 'text-green-500'}>{totalReturn >=0 ? '+' : ''}¥{totalReturn.toLocaleString('zh-CN', { maximumFractionDigits: 0 })}</span>
                </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className={`absolute right-0 top-0 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 ${dayProfit >= 0 ? 'bg-red-500/10' : 'bg-green-500/10'}`}></div>
            <div className="relative z-10">
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <TrendingUp className="w-5 h-5" />
                    <span className="text-sm font-medium">当日预估盈亏</span>
                </div>
                <div className={`text-3xl font-bold ${dayProfit >= 0 ? 'text-red-500' : 'text-green-500'}`}>
                    {isAppLoading ? (
                        <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `${dayProfit >= 0 ? '+' : ''}¥${Math.abs(dayProfit).toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                <div className="text-sm text-gray-400 mt-1">
                    基于实时估值计算
                </div>
            </div>
          </div>

          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-2xl p-6 shadow-lg text-white relative overflow-hidden">
             <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
             <div className="relative z-10 h-full flex flex-col justify-between">
                <div>
                    <h3 className="text-lg font-semibold mb-1">AI 市场洞察</h3>
                    <p className="text-indigo-200 text-sm">Gemini 3 实时分析已就绪。</p>
                </div>
                <button className="self-start mt-4 bg-white/20 hover:bg-white/30 backdrop-blur-sm px-4 py-2 rounded-lg text-sm font-medium transition-colors">
                    查看详细报告
                </button>
             </div>
          </div>
        </div>

        {/* Fund List */}
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <h2 className="text-lg font-bold text-gray-900 dark:text-white">自选基金</h2>
            <div className="flex gap-3">
              <div className="relative">
                <Search className="w-5 h-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input 
                  type="text" 
                  placeholder="搜索代码/名称..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none w-full sm:w-64"
                />
              </div>
              <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
              >
                <Plus className="w-4 h-4" />
                添加
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 dark:bg-gray-900/50 text-xs uppercase tracking-wider text-gray-500">
                  <th className="px-6 py-4 font-medium">基金名称</th>
                  <th className="px-6 py-4 font-medium text-right">估算净值</th>
                  <th className="px-6 py-4 font-medium text-right">估算涨幅</th>
                  <th className="px-6 py-4 font-medium text-right">持有收益 (估算)</th>
                  <th className="px-6 py-4 font-medium text-center">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {isAppLoading ? (
                    // Skeleton Rows for Initial Loading
                    <>
                        <SkeletonRow />
                        <SkeletonRow />
                        <SkeletonRow />
                    </>
                ) : (
                    filteredFunds.map(fund => {
                      const holding = holdings[fund.code];
                      const profit = holding ? holding.amount * (fund.estimatedValue - holding.cost) : 0;
                      const isPositive = fund.growthRate >= 0;
                      const profitIsPositive = profit >= 0;
                      const isError = fund.status === 'error';

                      return (
                        <tr 
                            key={fund.code} 
                            className={`group transition-colors cursor-pointer border-l-4 ${isError ? 'border-l-red-400 bg-red-50/30' : 'border-l-transparent hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}
                            onClick={() => setSelectedFundCode(fund.code)}
                        >
                          <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                                <div>
                                    <div className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                        {fund.name}
                                        {isError && <AlertCircle className="w-4 h-4 text-red-500" title="更新失败" />}
                                    </div>
                                    <div className="text-xs text-gray-500 font-mono">{fund.code}</div>
                                </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-right font-mono text-gray-700 dark:text-gray-300">
                            {fund.estimatedValue.toFixed(4)}
                          </td>
                          <td className={`px-6 py-4 text-right font-bold font-mono ${isPositive ? 'text-red-500' : 'text-green-500'}`}>
                            {isPositive ? '+' : ''}{fund.growthRate}%
                          </td>
                          <td className={`px-6 py-4 text-right font-medium ${holding ? (profitIsPositive ? 'text-red-500' : 'text-green-500') : 'text-gray-400'}`}>
                            {holding ? `¥${profit.toLocaleString('zh-CN', {maximumFractionDigits: 2})}` : '-'}
                          </td>
                          <td className="px-6 py-4 text-center">
                            <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button 
                                    className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                                    title="查看详情"
                                >
                                    <Eye className="w-4 h-4" />
                                </button>
                                <button 
                                    className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                                    onClick={(e) => handleDeleteClick(e, fund.code)}
                                    title="删除基金"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                )}
              </tbody>
            </table>
          </div>

          {!isAppLoading && filteredFunds.length === 0 && (
            <div className="p-12 text-center flex flex-col items-center justify-center text-gray-400">
                <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-full mb-4">
                    <Search className="w-8 h-8 text-gray-300" />
                </div>
                <p>{funds.length === 0 ? "暂无自选基金，请点击上方“添加”按钮" : "未找到匹配的基金"}</p>
            </div>
          )}
        </div>
      </main>

      <FundDetailModal 
        fund={selectedFund} 
        onClose={() => setSelectedFundCode(null)} 
        holding={selectedFundCode ? holdings[selectedFundCode] : undefined}
        onUpdateHolding={handleUpdateHolding}
        onDelete={() => selectedFundCode && executeDelete(selectedFundCode)}
      />

      {isAddModalOpen && (
        <AddFundModal 
          onClose={() => setIsAddModalOpen(false)}
          onAdd={handleAddFund}
          existingCodes={funds.map(f => f.code)}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef } from 'react';
import { fetchFundRealtime } from './services/fundService';
import { Fund, Holding } from './types';
import FundDetailModal from './components/FundDetailModal';
import AddFundModal from './components/AddFundModal';
import { Search, Plus, TrendingUp, RefreshCw, Eye, Wallet, Trash2, Clock, PlayCircle, PauseCircle, AlertCircle } from 'lucide-react';

const getMarketStatus = () => {
  const now = new Date();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const time = hour * 60 + minute;

  // Weekend
  if (day === 0 || day === 6) return { text: '休市中', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };

  // 9:15 - 9:30 Pre-market
  if (time >= 9 * 60 + 15 && time < 9 * 60 + 30) {
      return { text: '盘前交易', color: 'bg-orange-50 text-orange-600 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800' };
  }
  // 9:30 - 11:30 Open
  if (time >= 9 * 60 + 30 && time < 11 * 60 + 30) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }
  // 11:30 - 13:00 Break
  if (time >= 11 * 60 + 30 && time < 13 * 60) {
      return { text: '午间休市', color: 'bg-gray-50 text-gray-600 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
  }
  // 13:00 - 15:00 Open
  if (time >= 13 * 60 && time < 15 * 60) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }

  return { text: '已收盘', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
};

const SkeletonRow = () => (
  <tr className="animate-pulse border-b border-gray-100 dark:border-gray-700">
    <td className="px-6 py-4">
      <div className="flex flex-col gap-2">
        <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-32"></div>
        <div className="h-3 bg-gray-100 dark:bg-gray-800 rounded w-16"></div>
      </div>
    </td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-16 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-12 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-20 ml-auto"></div></td>
    <td className="px-6 py-4 text-center"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-8 mx-auto"></div></td>
  </tr>
);

export default function App() {
  const [funds, setFunds] = useState<Fund[]>([]);
  const [holdings, setHoldings] = useState<Record<string, Holding>>({});
  const [selectedFundCode, setSelectedFundCode] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isAutoRefresh, setIsAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [lastUpdated, setLastUpdated] = useState<string>('');
  const [marketStatus, setMarketStatus] = useState(getMarketStatus());

  // Loading States
  const [isAppLoading, setIsAppLoading] = useState(true); // Initial load
  const [isRefreshing, setIsRefreshing] = useState(false); // Manual/Auto refresh

  // Refs for checking current state inside async functions
  const fundsRef = useRef<Fund[]>([]);

  // Keep ref in sync
  useEffect(() => {
    fundsRef.current = funds;
  }, [funds]);

  // Initial Load with Persistence
  useEffect(() => {
    const init = async () => {
      // Load codes and holdings from LocalStorage
      const savedCodesStr = localStorage.getItem('fund_codes');
      const savedHoldingsStr = localStorage.getItem('fund_holdings');

      let codesToFetch: string[] = [];
      let hasSavedCodes = false;

      // Parse Holdings
      if (savedHoldingsStr) {
          try {
              setHoldings(JSON.parse(savedHoldingsStr));
          } catch (e) {
              console.error('Failed to parse saved holdings', e);
          }
      }

      // Parse Codes
      if (savedCodesStr) {
          try {
              const parsed = JSON.parse(savedCodesStr);
              if (Array.isArray(parsed)) {
                  codesToFetch = parsed;
                  hasSavedCodes = true;
              }
          } catch (e) {
              console.error('Failed to parse saved codes', e);
          }
      } 

      // Only set defaults if user has NEVER saved codes before (fresh user)
      // If user saved an empty list "[]", hasSavedCodes is true, so we honor the empty list.
      if (!hasSavedCodes) {
          codesToFetch = ['005827', '012414'];
          setHoldings({
              '005827': { fundCode: '005827', amount: 1000, cost: 2.100 },
              '012414': { fundCode: '012414', amount: 5000, cost: 0.950 },
          });
      }

      // Initial Fetch
      if (codesToFetch.length > 0) {
        await refreshFunds(codesToFetch, true);
      } else {
        setFunds([]);
      }

      setIsAppLoading(false);
    };

    init();

    // Market Status Timer
    const timer = setInterval(() => setMarketStatus(getMarketStatus()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Persistence: Save when changed
  // Note: We use isAppLoading to prevent saving empty states during initialization
  useEffect(() => {
    if (!isAppLoading) {
        const codes = funds.map(f => f.code);
        localStorage.setItem('fund_codes', JSON.stringify(codes));
    }
  }, [funds, isAppLoading]);

  useEffect(() => {
    if (!isAppLoading) {
        localStorage.setItem('fund_holdings', JSON.stringify(holdings));
    }
  }, [holdings, isAppLoading]);

  // Core Refresh Logic
  const refreshFunds = async (specificCodes?: string[], isInitial: boolean = false) => {
    if (!isInitial) setIsRefreshing(true);

    // Determine which codes to fetch. 
    // If specificCodes provided (e.g. Init), use them.
    // Otherwise use current funds from Ref to ensure we don't use stale closure data.
    const codesToFetch = specificCodes || fundsRef.current.map(f => f.code);

    if (codesToFetch.length === 0) {
        if (specificCodes) setFunds([]);
        if (!isInitial) setIsRefreshing(false);
        return;
    }

    const results = await Promise.all(codesToFetch.map(async (code) => {
        try {
            const fund = await fetchFundRealtime(code);
            return { ...fund, status: 'ok' as const };
        } catch (e) {
            // If fetching fails, we try to find the existing data to preserve it
            // or return an error placeholder
            const existing = fundsRef.current.find(f => f.code === code);
            if (existing) {
                return { ...existing, status: 'error' as const };
            }
            return { 
                code, 
                name: '加载失败', 
                netValue: 0, 
                estimatedValue: 0, 
                growthRate: 0, 
                updateTime: '--:--', 
                tags: [], 
                status: 'error' as const 
            };
        }
    }));

    // State Update Logic to handle Race Conditions (like Deletion during refresh)
    setFunds(prevFunds => {
         // If this was an explicit load (Init), we trust the results completely
         if (specificCodes) {
             return results;
         }

         // For auto-refresh, we only update funds that STILL exist in the state.
         // This prevents a deleted fund from reappearing if the network request finishes after deletion.
         return prevFunds.map(prevFund => {
             const newData = results.find(r => r.code === prevFund.code);
             return newData || prevFund;
         });
    });

    const now = new Date();
    setLastUpdated(`${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`);

    if (!isInitial) setIsRefreshing(false);
  };

  // Auto-Refresh Loop
  useEffect(() => {
    if (!isAutoRefresh || isAppLoading) return;
    const intervalId = setInterval(() => {
      refreshFunds();
    }, 60000); 
    return () => clearInterval(intervalId);
  }, [isAutoRefresh, isAppLoading]); // No need to depend on funds, refreshFunds reads from ref

  const handleUpdateHolding = (amount: number, cost: number) => {
    if (!selectedFundCode) return;
    setHoldings(prev => ({
      ...prev,
      [selectedFundCode]: { fundCode: selectedFundCode, amount, cost }
    }));
  };

  const handleAddFund = async (code: string, amount: number, cost: number) => {
    try {
        const newFund = await fetchFundRealtime(code);
        setFunds(prev => {
            if(prev.find(f => f.code === code)) return prev;
            return [{ ...newFund, status: 'ok' }, ...prev];
        });

        if (amount > 0 || cost > 0) {
            setHoldings(prev => ({
                ...prev,
                [code]: { fundCode: code, amount, cost }
            }));
        }

        setIsAddModalOpen(false);
    } catch (e) {
        console.error("Error adding fund", e);
        throw e;
    }
  };

  const executeDelete = (code: string) => {
      if (confirm('确定要删除这个基金吗？')) {
          // 1. Remove from State immediately
          setFunds(prev => prev.filter(f => f.code !== code));
          setHoldings(prev => {
              const next = { ...prev };
              delete next[code];
              return next;
          });

          if (selectedFundCode === code) {
              setSelectedFundCode(null);
          }

          // 2. We primarily rely on the useEffect hook to sync to localStorage
          // However, we can also force a sync here if we are worried about immediate tab closure.
          // Since we updated state, the effect will run shortly. 
          // But to be absolutely safe for the "delete and run" user:
          try {
            // Read mostly-fresh state from logic (since state update is async, filter manually again)
            // Note: funds state variable is from the render scope, so it contains the item we just decided to delete.
            const codes = funds.filter(f => f.code !== code).map(f => f.code);
            localStorage.setItem('fund_codes', JSON.stringify(codes));
          } catch(e) { console.error('Manual save failed', e) }
      }
  };

  const handleDeleteClick = (e: React.MouseEvent, code: string) => {
      e.stopPropagation();
      executeDelete(code);
  };

  const selectedFund = funds.find(f => f.code === selectedFundCode) || null;
  const holdingsValues = Object.values(holdings) as Holding[];

  // Stats Calculations
  const totalAssets = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    return sum + (fund ? fund.estimatedValue * holding.amount : 0);
  }, 0);

  const dayProfit = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    if (!fund) return sum;
    return sum + (holding.amount * (fund.estimatedValue - fund.netValue));
  }, 0);

  const totalReturn = holdingsValues.reduce<number>((sum, holding) => {
      const fund = funds.find(f => f.code === holding.fundCode);
      if (!fund) return sum;
      return sum + ((fund.estimatedValue * holding.amount) - (holding.amount * holding.cost));
  }, 0);

  const filteredFunds = funds.filter(f => 
    f.name.includes(searchTerm) || f.code.includes(searchTerm)
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 font-sans">
      {/* Navbar */}
      <nav className="sticky top-0 z-30 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-gray-200 dark:border-gray-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg">
                <TrendingUp className="w-6 h-6 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600 dark:from-blue-400 dark:to-indigo-400 leading-none">
                    基金智投 AI
                </h1>
                <span className="text-xs text-gray-400 mt-1">实盘估值监控</span>
              </div>
            </div>

            {/* Market Status Indicator */}
            <div className={`hidden md:flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-medium ${marketStatus.color}`}>
                <div className={`w-1.5 h-1.5 rounded-full ${marketStatus.active ? 'bg-green-500 animate-pulse' : 'bg-gray-400'}`}></div>
                <Clock className="w-3 h-3" />
                {marketStatus.text}
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
              {/* Auto Refresh Toggle */}
              <button
                onClick={() => setIsAutoRefresh(!isAutoRefresh)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                  isAutoRefresh 
                    ? 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' 
                    : 'bg-gray-50 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700'
                }`}
                title={isAutoRefresh ? "点击暂停自动刷新" : "点击开启自动刷新"}
              >
                {isAutoRefresh ? <PauseCircle className="w-3.5 h-3.5" /> : <PlayCircle className="w-3.5 h-3.5" />}
                <span className="hidden sm:inline">{isAutoRefresh ? '自动刷新' : '已暂停'}</span>
              </button>

              <div className="hidden sm:block text-xs text-gray-400 text-right">
                  <div>更新: {lastUpdated}</div>
                  <div className="md:hidden text-[10px]">{marketStatus.text}</div>
              </div>
              <button 
                onClick={() => {
                    refreshFunds();
                }}
                disabled={isRefreshing}
                className={`p-2 rounded-full transition-all bg-gray-100 text-gray-500 hover:bg-blue-100 hover:text-blue-600 dark:bg-gray-800 dark:hover:bg-blue-900/30 dark:hover:text-blue-400 ${isRefreshing ? 'animate-spin text-blue-600 bg-blue-50' : ''}`}
                title="刷新数据"
              >
                <RefreshCw className={`w-5 h-5`} />
              </button>
              <div className="h-8 w-8 rounded-full bg-gradient-to-tr from-blue-500 to-purple-500"></div>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Dashboard Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className="absolute right-0 top-0 w-32 h-32 bg-blue-500/10 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <Wallet className="w-5 h-5" />
                    <span className="text-sm font-medium">总资产</span>
                </div>
                <div className="text-3xl font-bold text-gray-900 dark:text-white">
                    {isAppLoading ? (
                         <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `¥${totalAssets.toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                 <div className="text-sm text-gray-400 mt-1">
                    总盈亏: <span className={totalReturn >= 0 ? 'text-red-500' : 'text-green-500'}>{totalReturn >=0 ? '+' : ''}¥{totalReturn.toLocaleString('zh-CN', { maximumFractionDigits: 0 })}</span>
                </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className={`absolute right-0 top-0 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 ${dayProfit >= 0 ? 'bg-red-500/10' : 'bg-green-500/10'}`}></div>
            <div className="relative z-10">
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <TrendingUp className="w-5 h-5" />
                    <span className="text-sm font-medium">当日预估盈亏</span>
                </div>
                <div className={`text-3xl font-bold ${dayProfit >= 0 ? 'text-red-500' : 'text-green-500'}`}>
                    {isAppLoading ? (
                        <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `${dayProfit >= 0 ? '+' : ''}¥${Math.abs(dayProfit).toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                <div className="text-sm text-gray-400 mt-1">
                    基于实时估值计算
                </div>
            </div>
          </div>

          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-2xl p-6 shadow-lg text-white relative overflow-hidden">
             <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
             <div className="relative z-10 h-full flex flex-col justify-between">
                <div>
                    <h3 className="text-lg font-semibold mb-1">AI 市场洞察</h3>
                    <p className="text-indigo-200 text-sm">Gemini 3 实时分析已就绪。</p>
                </div>
                <button className="self-start mt-4 bg-white/20 hover:bg-white/30 backdrop-blur-sm px-4 py-2 rounded-lg text-sm font-medium transition-colors">
                    查看详细报告
                </button>
             </div>
          </div>
        </div>

        {/* Fund List */}
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <h2 className="text-lg font-bold text-gray-900 dark:text-white">自选基金</h2>
            <div className="flex gap-3">
              <div className="relative">
                <Search className="w-5 h-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input 
                  type="text" 
                  placeholder="搜索代码/名称..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none w-full sm:w-64"
                />
              </div>
              <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
              >
                <Plus className="w-4 h-4" />
                添加
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 dark:bg-gray-900/50 text-xs uppercase tracking-wider text-gray-500">
                  <th className="px-6 py-4 font-medium">基金名称</th>
                  <th className="px-6 py-4 font-medium text-right">估算净值</th>
                  <th className="px-6 py-4 font-medium text-right">估算涨幅</th>
                  <th className="px-6 py-4 font-medium text-right">持有收益 (估算)</th>
                  <th className="px-6 py-4 font-medium text-center">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {isAppLoading ? (
                    // Skeleton Rows for Initial Loading
                    <>
                        <SkeletonRow />
                        <SkeletonRow />
                        <SkeletonRow />
                    </>
                ) : (
                    filteredFunds.map(fund => {
                      const holding = holdings[fund.code];
                      const profit = holding ? holding.amount * (fund.estimatedValue - holding.cost) : 0;
                      const isPositive = fund.growthRate >= 0;
                      const profitIsPositive = profit >= 0;
                      const isError = fund.status === 'error';

                      return (
                        <tr 
                            key={fund.code} 
                            className={`group transition-colors cursor-pointer border-l-4 ${isError ? 'border-l-red-400 bg-red-50/30' : 'border-l-transparent hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}
                            onClick={() => setSelectedFundCode(fund.code)}
                        >
                          <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                                <div>
                                    <div className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                        {fund.name}
                                        {isError && <AlertCircle className="w-4 h-4 text-red-500" title="更新失败" />}
                                    </div>
                                    <div className="text-xs text-gray-500 font-mono">{fund.code}</div>
                                </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-right font-mono text-gray-700 dark:text-gray-300">
                            {fund.estimatedValue.toFixed(4)}
                          </td>
                          <td className={`px-6 py-4 text-right font-bold font-mono ${isPositive ? 'text-red-500' : 'text-green-500'}`}>
                            {isPositive ? '+' : ''}{fund.growthRate}%
                          </td>
                          <td className={`px-6 py-4 text-right font-medium ${holding ? (profitIsPositive ? 'text-red-500' : 'text-green-500') : 'text-gray-400'}`}>
                            {holding ? `¥${profit.toLocaleString('zh-CN', {maximumFractionDigits: 2})}` : '-'}
                          </td>
                          <td className="px-6 py-4 text-center">
                            <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button 
                                    className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                                    title="查看详情"
                                >
                                    <Eye className="w-4 h-4" />
                                </button>
                                <button 
                                    className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                                    onClick={(e) => handleDeleteClick(e, fund.code)}
                                    title="删除基金"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                )}
              </tbody>
            </table>
          </div>

          {!isAppLoading && filteredFunds.length === 0 && (
            <div className="p-12 text-center flex flex-col items-center justify-center text-gray-400">
                <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-full mb-4">
                    <Search className="w-8 h-8 text-gray-300" />
                </div>
                <p>{funds.length === 0 ? "暂无自选基金，请点击上方“添加”按钮" : "未找到匹配的基金"}</p>
            </div>
          )}
        </div>
      </main>

      <FundDetailModal 
        fund={selectedFund} 
        onClose={() => setSelectedFundCode(null)} 
        holding={selectedFundCode ? holdings[selectedFundCode] : undefined}
        onUpdateHolding={handleUpdateHolding}
        onDelete={() => selectedFundCode && executeDelete(selectedFundCode)}
      />

      {isAddModalOpen && (
        <AddFundModal 
          onClose={() => setIsAddModalOpen(false)}
          onAdd={handleAddFund}
          existingCodes={funds.map(f => f.code)}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { fetchFundRealtime } from './services/fundService';
import { Fund, Holding } from './types';
import FundDetailModal from './components/FundDetailModal';
import AddFundModal from './components/AddFundModal';
import { Search, Plus, TrendingUp, RefreshCw, Eye, Wallet, Trash2, Clock, PlayCircle, PauseCircle, AlertCircle } from 'lucide-react';

const getMarketStatus = () => {
  const now = new Date();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const time = hour * 60 + minute;

  // Weekend
  if (day === 0 || day === 6) return { text: '休市中', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };

  // 9:15 - 9:30 Pre-market
  if (time >= 9 * 60 + 15 && time < 9 * 60 + 30) {
      return { text: '盘前交易', color: 'bg-orange-50 text-orange-600 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800' };
  }
  // 9:30 - 11:30 Open
  if (time >= 9 * 60 + 30 && time < 11 * 60 + 30) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }
  // 11:30 - 13:00 Break
  if (time >= 11 * 60 + 30 && time < 13 * 60) {
      return { text: '午间休市', color: 'bg-gray-50 text-gray-600 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
  }
  // 13:00 - 15:00 Open
  if (time >= 13 * 60 && time < 15 * 60) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }

  return { text: '已收盘', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
};

const SkeletonRow = () => (
  <tr className="animate-pulse border-b border-gray-100 dark:border-gray-700">
    <td className="px-6 py-4">
      <div className="flex flex-col gap-2">
        <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-32"></div>
        <div className="h-3 bg-gray-100 dark:bg-gray-800 rounded w-16"></div>
      </div>
    </td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-16 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-12 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-20 ml-auto"></div></td>
    <td className="px-6 py-4 text-center"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-8 mx-auto"></div></td>
  </tr>
);

export default function App() {
  const [funds, setFunds] = useState<Fund[]>([]);
  const [holdings, setHoldings] = useState<Record<string, Holding>>({});
  const [selectedFundCode, setSelectedFundCode] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isAutoRefresh, setIsAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [lastUpdated, setLastUpdated] = useState<string>('');
  const [marketStatus, setMarketStatus] = useState(getMarketStatus());

  // Loading States
  const [isAppLoading, setIsAppLoading] = useState(true); // Initial load
  const [isRefreshing, setIsRefreshing] = useState(false); // Manual/Auto refresh

  // Refs for checking current state inside async functions
  const fundsRef = useRef<Fund[]>([]);

  // Keep ref in sync
  useEffect(() => {
    fundsRef.current = funds;
  }, [funds]);

  // Initial Load with Persistence
  useEffect(() => {
    const init = async () => {
      // Load codes and holdings from LocalStorage
      const savedCodesStr = localStorage.getItem('fund_codes');
      const savedHoldingsStr = localStorage.getItem('fund_holdings');

      let codesToFetch: string[] = [];
      let hasSavedCodes = false;

      // Parse Holdings
      if (savedHoldingsStr) {
          try {
              setHoldings(JSON.parse(savedHoldingsStr));
          } catch (e) {
              console.error('Failed to parse saved holdings', e);
          }
      }

      // Parse Codes
      if (savedCodesStr) {
          try {
              const parsed = JSON.parse(savedCodesStr);
              if (Array.isArray(parsed)) {
                  codesToFetch = parsed;
                  hasSavedCodes = true;
              }
          } catch (e) {
              console.error('Failed to parse saved codes', e);
          }
      } 

      // Only set defaults if user has NEVER saved codes before (fresh user)
      // If user saved an empty list "[]", hasSavedCodes is true, so we honor the empty list.
      if (!hasSavedCodes) {
          codesToFetch = ['005827', '012414'];
          setHoldings({
              '005827': { fundCode: '005827', amount: 1000, cost: 2.100 },
              '012414': { fundCode: '012414', amount: 5000, cost: 0.950 },
          });
      }

      // Initial Fetch
      if (codesToFetch.length > 0) {
        await refreshFunds(codesToFetch, true);
      } else {
        setFunds([]);
      }

      setIsAppLoading(false);
    };

    init();

    // Market Status Timer
    const timer = setInterval(() => setMarketStatus(getMarketStatus()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Persistence: Save when changed
  // Note: We use isAppLoading to prevent saving empty states during initialization
  useEffect(() => {
    if (!isAppLoading) {
        const codes = funds.map(f => f.code);
        localStorage.setItem('fund_codes', JSON.stringify(codes));
    }
  }, [funds, isAppLoading]);

  useEffect(() => {
    if (!isAppLoading) {
        localStorage.setItem('fund_holdings', JSON.stringify(holdings));
    }
  }, [holdings, isAppLoading]);

  // Core Refresh Logic
  const refreshFunds = async (specificCodes?: string[], isInitial: boolean = false) => {
    if (!isInitial) setIsRefreshing(true);

    // Determine which codes to fetch. 
    // If specificCodes provided (e.g. Init), use them.
    // Otherwise use current funds from Ref to ensure we don't use stale closure data.
    const codesToFetch = specificCodes || fundsRef.current.map(f => f.code);

    if (codesToFetch.length === 0) {
        if (specificCodes) setFunds([]);
        if (!isInitial) setIsRefreshing(false);
        return;
    }

    const results = await Promise.all(codesToFetch.map(async (code) => {
        try {
            const fund = await fetchFundRealtime(code);
            return { ...fund, status: 'ok' as const };
        } catch (e) {
            // If fetching fails, we try to find the existing data to preserve it
            // or return an error placeholder
            const existing = fundsRef.current.find(f => f.code === code);
            if (existing) {
                return { ...existing, status: 'error' as const };
            }
            return { 
                code, 
                name: '加载失败', 
                netValue: 0, 
                estimatedValue: 0, 
                growthRate: 0, 
                updateTime: '--:--', 
                tags: [], 
                status: 'error' as const 
            };
        }
    }));

    // State Update Logic to handle Race Conditions (like Deletion during refresh)
    setFunds(prevFunds => {
         // If this was an explicit load (Init), we trust the results completely
         if (specificCodes) {
             return results;
         }

         // For auto-refresh, we only update funds that STILL exist in the state.
         // This prevents a deleted fund from reappearing if the network request finishes after deletion.
         return prevFunds.map(prevFund => {
             const newData = results.find(r => r.code === prevFund.code);
             return newData || prevFund;
         });
    });

    const now = new Date();
    setLastUpdated(`${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`);

    if (!isInitial) setIsRefreshing(false);
  };

  // Auto-Refresh Loop
  useEffect(() => {
    if (!isAutoRefresh || isAppLoading) return;
    const intervalId = setInterval(() => {
      refreshFunds();
    }, 60000); 
    return () => clearInterval(intervalId);
  }, [isAutoRefresh, isAppLoading]); // No need to depend on funds, refreshFunds reads from ref

  const handleUpdateHolding = (amount: number, cost: number) => {
    if (!selectedFundCode) return;
    setHoldings(prev => ({
      ...prev,
      [selectedFundCode]: { fundCode: selectedFundCode, amount, cost }
    }));
  };

  const handleAddFund = async (code: string, amount: number, cost: number) => {
    try {
        const newFund = await fetchFundRealtime(code);
        setFunds(prev => {
            if(prev.find(f => f.code === code)) return prev;
            return [{ ...newFund, status: 'ok' }, ...prev];
        });

        if (amount > 0 || cost > 0) {
            setHoldings(prev => ({
                ...prev,
                [code]: { fundCode: code, amount, cost }
            }));
        }

        setIsAddModalOpen(false);
    } catch (e) {
        console.error("Error adding fund", e);
        throw e;
    }
  };

  const executeDelete = (code: string) => {
      if (confirm('确定要删除这个基金吗？')) {
          // 1. Remove from State immediately
          setFunds(prev => prev.filter(f => f.code !== code));
          setHoldings(prev => {
              const next = { ...prev };
              delete next[code];
              return next;
          });

          if (selectedFundCode === code) {
              setSelectedFundCode(null);
          }

          // 2. We primarily rely on the useEffect hook to sync to localStorage
          // However, we can also force a sync here if we are worried about immediate tab closure.
          // Since we updated state, the effect will run shortly. 
          // But to be absolutely safe for the "delete and run" user:
          try {
            // Read mostly-fresh state from logic (since state update is async, filter manually again)
            // Note: funds state variable is from the render scope, so it contains the item we just decided to delete.
            const codes = funds.filter(f => f.code !== code).map(f => f.code);
            localStorage.setItem('fund_codes', JSON.stringify(codes));
          } catch(e) { console.error('Manual save failed', e) }
      }
  };

  const handleDeleteClick = (e: React.MouseEvent, code: string) => {
      e.stopPropagation();
      executeDelete(code);
  };

  const selectedFund = funds.find(f => f.code === selectedFundCode) || null;
  const holdingsValues = Object.values(holdings) as Holding[];

  // Stats Calculations
  const totalAssets = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    return sum + (fund ? fund.estimatedValue * holding.amount : 0);
  }, 0);

  const dayProfit = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    if (!fund) return sum;
    return sum + (holding.amount * (fund.estimatedValue - fund.netValue));
  }, 0);

  const totalReturn = holdingsValues.reduce<number>((sum, holding) => {
      const fund = funds.find(f => f.code === holding.fundCode);
      if (!fund) return sum;
      return sum + ((fund.estimatedValue * holding.amount) - (holding.amount * holding.cost));
  }, 0);

  const filteredFunds = funds.filter(f => 
    f.name.includes(searchTerm) || f.code.includes(searchTerm)
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 font-sans">
      {/* Navbar */}
      <nav className="sticky top-0 z-30 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-gray-200 dark:border-gray-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg">
                <TrendingUp className="w-6 h-6 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600 dark:from-blue-400 dark:to-indigo-400 leading-none">
                    基金智投 AI
                </h1>
                <span className="text-xs text-gray-400 mt-1">实盘估值监控</span>
              </div>
            </div>

            {/* Market Status Indicator */}
            <div className={`hidden md:flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-medium ${marketStatus.color}`}>
                <div className={`w-1.5 h-1.5 rounded-full ${marketStatus.active ? 'bg-green-500 animate-pulse' : 'bg-gray-400'}`}></div>
                <Clock className="w-3 h-3" />
                {marketStatus.text}
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
              {/* Auto Refresh Toggle */}
              <button
                onClick={() => setIsAutoRefresh(!isAutoRefresh)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                  isAutoRefresh 
                    ? 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' 
                    : 'bg-gray-50 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700'
                }`}
                title={isAutoRefresh ? "点击暂停自动刷新" : "点击开启自动刷新"}
              >
                {isAutoRefresh ? <PauseCircle className="w-3.5 h-3.5" /> : <PlayCircle className="w-3.5 h-3.5" />}
                <span className="hidden sm:inline">{isAutoRefresh ? '自动刷新' : '已暂停'}</span>
              </button>

              <div className="hidden sm:block text-xs text-gray-400 text-right">
                  <div>更新: {lastUpdated}</div>
                  <div className="md:hidden text-[10px]">{marketStatus.text}</div>
              </div>
              <button 
                onClick={() => {
                    refreshFunds();
                }}
                disabled={isRefreshing}
                className={`p-2 rounded-full transition-all bg-gray-100 text-gray-500 hover:bg-blue-100 hover:text-blue-600 dark:bg-gray-800 dark:hover:bg-blue-900/30 dark:hover:text-blue-400 ${isRefreshing ? 'animate-spin text-blue-600 bg-blue-50' : ''}`}
                title="刷新数据"
              >
                <RefreshCw className={`w-5 h-5`} />
              </button>
              <div className="h-8 w-8 rounded-full bg-gradient-to-tr from-blue-500 to-purple-500"></div>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Dashboard Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className="absolute right-0 top-0 w-32 h-32 bg-blue-500/10 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <Wallet className="w-5 h-5" />
                    <span className="text-sm font-medium">总资产</span>
                </div>
                <div className="text-3xl font-bold text-gray-900 dark:text-white">
                    {isAppLoading ? (
                         <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `¥${totalAssets.toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                 <div className="text-sm text-gray-400 mt-1">
                    总盈亏: <span className={totalReturn >= 0 ? 'text-red-500' : 'text-green-500'}>{totalReturn >=0 ? '+' : ''}¥{totalReturn.toLocaleString('zh-CN', { maximumFractionDigits: 0 })}</span>
                </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className={`absolute right-0 top-0 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 ${dayProfit >= 0 ? 'bg-red-500/10' : 'bg-green-500/10'}`}></div>
            <div className="relative z-10">
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <TrendingUp className="w-5 h-5" />
                    <span className="text-sm font-medium">当日预估盈亏</span>
                </div>
                <div className={`text-3xl font-bold ${dayProfit >= 0 ? 'text-red-500' : 'text-green-500'}`}>
                    {isAppLoading ? (
                        <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `${dayProfit >= 0 ? '+' : ''}¥${Math.abs(dayProfit).toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                <div className="text-sm text-gray-400 mt-1">
                    基于实时估值计算
                </div>
            </div>
          </div>

          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-2xl p-6 shadow-lg text-white relative overflow-hidden">
             <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
             <div className="relative z-10 h-full flex flex-col justify-between">
                <div>
                    <h3 className="text-lg font-semibold mb-1">AI 市场洞察</h3>
                    <p className="text-indigo-200 text-sm">Gemini 3 实时分析已就绪。</p>
                </div>
                <button className="self-start mt-4 bg-white/20 hover:bg-white/30 backdrop-blur-sm px-4 py-2 rounded-lg text-sm font-medium transition-colors">
                    查看详细报告
                </button>
             </div>
          </div>
        </div>

        {/* Fund List */}
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <h2 className="text-lg font-bold text-gray-900 dark:text-white">自选基金</h2>
            <div className="flex gap-3">
              <div className="relative">
                <Search className="w-5 h-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input 
                  type="text" 
                  placeholder="搜索代码/名称..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none w-full sm:w-64"
                />
              </div>
              <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
              >
                <Plus className="w-4 h-4" />
                添加
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 dark:bg-gray-900/50 text-xs uppercase tracking-wider text-gray-500">
                  <th className="px-6 py-4 font-medium">基金名称</th>
                  <th className="px-6 py-4 font-medium text-right">估算净值</th>
                  <th className="px-6 py-4 font-medium text-right">估算涨幅</th>
                  <th className="px-6 py-4 font-medium text-right">持有收益 (估算)</th>
                  <th className="px-6 py-4 font-medium text-center">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {isAppLoading ? (
                    // Skeleton Rows for Initial Loading
                    <>
                        <SkeletonRow />
                        <SkeletonRow />
                        <SkeletonRow />
                    </>
                ) : (
                    filteredFunds.map(fund => {
                      const holding = holdings[fund.code];
                      const profit = holding ? holding.amount * (fund.estimatedValue - holding.cost) : 0;
                      const isPositive = fund.growthRate >= 0;
                      const profitIsPositive = profit >= 0;
                      const isError = fund.status === 'error';

                      return (
                        <tr 
                            key={fund.code} 
                            className={`group transition-colors cursor-pointer border-l-4 ${isError ? 'border-l-red-400 bg-red-50/30' : 'border-l-transparent hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}
                            onClick={() => setSelectedFundCode(fund.code)}
                        >
                          <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                                <div>
                                    <div className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                        {fund.name}
                                        {isError && (
                                            <span title="更新失败" className="flex items-center">
                                                <AlertCircle className="w-4 h-4 text-red-500" />
                                            </span>
                                        )}
                                    </div>
                                    <div className="text-xs text-gray-500 font-mono">{fund.code}</div>
                                </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-right font-mono text-gray-700 dark:text-gray-300">
                            {fund.estimatedValue.toFixed(4)}
                          </td>
                          <td className={`px-6 py-4 text-right font-bold font-mono ${isPositive ? 'text-red-500' : 'text-green-500'}`}>
                            {isPositive ? '+' : ''}{fund.growthRate}%
                          </td>
                          <td className={`px-6 py-4 text-right font-medium ${holding ? (profitIsPositive ? 'text-red-500' : 'text-green-500') : 'text-gray-400'}`}>
                            {holding ? `¥${profit.toLocaleString('zh-CN', {maximumFractionDigits: 2})}` : '-'}
                          </td>
                          <td className="px-6 py-4 text-center">
                            <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button 
                                    className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                                    title="查看详情"
                                >
                                    <Eye className="w-4 h-4" />
                                </button>
                                <button 
                                    className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                                    onClick={(e) => handleDeleteClick(e, fund.code)}
                                    title="删除基金"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                )}
              </tbody>
            </table>
          </div>

          {!isAppLoading && filteredFunds.length === 0 && (
            <div className="p-12 text-center flex flex-col items-center justify-center text-gray-400">
                <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-full mb-4">
                    <Search className="w-8 h-8 text-gray-300" />
                </div>
                <p>{funds.length === 0 ? "暂无自选基金，请点击上方“添加”按钮" : "未找到匹配的基金"}</p>
            </div>
          )}
        </div>
      </main>

      <FundDetailModal 
        fund={selectedFund} 
        onClose={() => setSelectedFundCode(null)} 
        holding={selectedFundCode ? holdings[selectedFundCode] : undefined}
        onUpdateHolding={handleUpdateHolding}
        onDelete={() => selectedFundCode && executeDelete(selectedFundCode)}
      />

      {isAddModalOpen && (
        <AddFundModal 
          onClose={() => setIsAddModalOpen(false)}
          onAdd={handleAddFund}
          existingCodes={funds.map(f => f.code)}
        />
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { fetchFundRealtime } from './services/fundService';
import { Fund, Holding } from './types';
import FundDetailModal from './components/FundDetailModal';
import AddFundModal from './components/AddFundModal';
import { Search, Plus, TrendingUp, RefreshCw, Eye, Wallet, Trash2, Clock, PlayCircle, PauseCircle, AlertCircle } from 'lucide-react';

const getMarketStatus = () => {
  const now = new Date();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const time = hour * 60 + minute;

  // Weekend
  if (day === 0 || day === 6) return { text: '休市中', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };

  // 9:15 - 9:30 Pre-market
  if (time >= 9 * 60 + 15 && time < 9 * 60 + 30) {
      return { text: '盘前交易', color: 'bg-orange-50 text-orange-600 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800' };
  }
  // 9:30 - 11:30 Open
  if (time >= 9 * 60 + 30 && time < 11 * 60 + 30) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }
  // 11:30 - 13:00 Break
  if (time >= 11 * 60 + 30 && time < 13 * 60) {
      return { text: '午间休市', color: 'bg-gray-50 text-gray-600 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
  }
  // 13:00 - 15:00 Open
  if (time >= 13 * 60 && time < 15 * 60) {
      return { text: '交易中', color: 'bg-green-50 text-green-600 border-green-200 dark:bg-green-900/20 dark:text-green-400 dark:border-green-800', active: true };
  }

  return { text: '已收盘', color: 'bg-gray-100 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700' };
};

const SkeletonRow = () => (
  <tr className="animate-pulse border-b border-gray-100 dark:border-gray-700">
    <td className="px-6 py-4">
      <div className="flex flex-col gap-2">
        <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-32"></div>
        <div className="h-3 bg-gray-100 dark:bg-gray-800 rounded w-16"></div>
      </div>
    </td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-16 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-12 ml-auto"></div></td>
    <td className="px-6 py-4 text-right"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-20 ml-auto"></div></td>
    <td className="px-6 py-4 text-center"><div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-8 mx-auto"></div></td>
  </tr>
);

export default function App() {
  const [funds, setFunds] = useState<Fund[]>([]);
  const [holdings, setHoldings] = useState<Record<string, Holding>>({});
  const [selectedFundCode, setSelectedFundCode] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isAutoRefresh, setIsAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [lastUpdated, setLastUpdated] = useState<string>('');
  const [marketStatus, setMarketStatus] = useState(getMarketStatus());

  // Loading States
  const [isAppLoading, setIsAppLoading] = useState(true); // Initial load
  const [isRefreshing, setIsRefreshing] = useState(false); // Manual/Auto refresh

  // Refs for checking current state inside async functions
  const fundsRef = useRef<Fund[]>([]);

  // Keep ref in sync
  useEffect(() => {
    fundsRef.current = funds;
  }, [funds]);

  // Initial Load with Persistence
  useEffect(() => {
    const init = async () => {
      // Load codes and holdings from LocalStorage
      const savedCodesStr = localStorage.getItem('fund_codes');
      const savedHoldingsStr = localStorage.getItem('fund_holdings');

      let codesToFetch: string[] = [];
      let hasSavedCodes = false;

      // Parse Holdings
      if (savedHoldingsStr) {
          try {
              setHoldings(JSON.parse(savedHoldingsStr));
          } catch (e) {
              console.error('Failed to parse saved holdings', e);
          }
      }

      // Parse Codes
      if (savedCodesStr) {
          try {
              const parsed = JSON.parse(savedCodesStr);
              if (Array.isArray(parsed)) {
                  codesToFetch = parsed;
                  hasSavedCodes = true;
              }
          } catch (e) {
              console.error('Failed to parse saved codes', e);
          }
      } 

      // Only set defaults if user has NEVER saved codes before (fresh user)
      // If user saved an empty list "[]", hasSavedCodes is true, so we honor the empty list.
      if (!hasSavedCodes) {
          codesToFetch = ['005827', '012414'];
          setHoldings({
              '005827': { fundCode: '005827', amount: 1000, cost: 2.100 },
              '012414': { fundCode: '012414', amount: 5000, cost: 0.950 },
          });
      }

      // Initial Fetch
      if (codesToFetch.length > 0) {
        await refreshFunds(codesToFetch, true);
      } else {
        setFunds([]);
      }

      setIsAppLoading(false);
    };

    init();

    // Market Status Timer
    const timer = setInterval(() => setMarketStatus(getMarketStatus()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Persistence: Save when changed
  // Note: We use isAppLoading to prevent saving empty states during initialization
  useEffect(() => {
    if (!isAppLoading) {
        const codes = funds.map(f => f.code);
        localStorage.setItem('fund_codes', JSON.stringify(codes));
    }
  }, [funds, isAppLoading]);

  useEffect(() => {
    if (!isAppLoading) {
        localStorage.setItem('fund_holdings', JSON.stringify(holdings));
    }
  }, [holdings, isAppLoading]);

  // Core Refresh Logic
  const refreshFunds = async (specificCodes?: string[], isInitial: boolean = false) => {
    if (!isInitial) setIsRefreshing(true);

    // Determine which codes to fetch. 
    // If specificCodes provided (e.g. Init), use them.
    // Otherwise use current funds from Ref to ensure we don't use stale closure data.
    const codesToFetch = specificCodes || fundsRef.current.map(f => f.code);

    if (codesToFetch.length === 0) {
        if (specificCodes) setFunds([]);
        if (!isInitial) setIsRefreshing(false);
        return;
    }

    const results = await Promise.all(codesToFetch.map(async (code) => {
        try {
            const fund = await fetchFundRealtime(code);
            return { ...fund, status: 'ok' as const };
        } catch (e) {
            // If fetching fails, we try to find the existing data to preserve it
            // or return an error placeholder
            const existing = fundsRef.current.find(f => f.code === code);
            if (existing) {
                return { ...existing, status: 'error' as const };
            }
            return { 
                code, 
                name: '加载失败', 
                netValue: 0, 
                estimatedValue: 0, 
                growthRate: 0, 
                updateTime: '--:--', 
                tags: [], 
                status: 'error' as const 
            };
        }
    }));

    // State Update Logic to handle Race Conditions (like Deletion during refresh)
    setFunds(prevFunds => {
         // If this was an explicit load (Init), we trust the results completely
         if (specificCodes) {
             return results;
         }

         // For auto-refresh, we only update funds that STILL exist in the state.
         // This prevents a deleted fund from reappearing if the network request finishes after deletion.
         return prevFunds.map(prevFund => {
             const newData = results.find(r => r.code === prevFund.code);
             return newData || prevFund;
         });
    });

    const now = new Date();
    setLastUpdated(`${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`);

    if (!isInitial) setIsRefreshing(false);
  };

  // Auto-Refresh Loop
  useEffect(() => {
    if (!isAutoRefresh || isAppLoading) return;
    const intervalId = setInterval(() => {
      refreshFunds();
    }, 60000); 
    return () => clearInterval(intervalId);
  }, [isAutoRefresh, isAppLoading]); // No need to depend on funds, refreshFunds reads from ref

  const handleUpdateHolding = (amount: number, cost: number) => {
    if (!selectedFundCode) return;
    setHoldings(prev => ({
      ...prev,
      [selectedFundCode]: { fundCode: selectedFundCode, amount, cost }
    }));
  };

  const handleAddFund = async (code: string, amount: number, cost: number) => {
    try {
        const newFund = await fetchFundRealtime(code);
        setFunds(prev => {
            if(prev.find(f => f.code === code)) return prev;
            return [{ ...newFund, status: 'ok' }, ...prev];
        });

        if (amount > 0 || cost > 0) {
            setHoldings(prev => ({
                ...prev,
                [code]: { fundCode: code, amount, cost }
            }));
        }

        setIsAddModalOpen(false);
    } catch (e) {
        console.error("Error adding fund", e);
        throw e;
    }
  };

  const executeDelete = (code: string) => {
      if (confirm('确定要删除这个基金吗？')) {
          // Remove from Funds State immediately.
          // Note: We intentionally DO NOT delete the holding record from 'holdings' state.
          // This allows us to "remember" the cost price if the user re-adds the fund later.
          // Since the main view iterates over 'funds', the orphaned holding won't be visible or affect calculations.
          setFunds(prev => prev.filter(f => f.code !== code));

          if (selectedFundCode === code) {
              setSelectedFundCode(null);
          }
      }
  };

  const handleDeleteClick = (e: React.MouseEvent, code: string) => {
      e.stopPropagation();
      executeDelete(code);
  };

  const selectedFund = funds.find(f => f.code === selectedFundCode) || null;
  const holdingsValues = Object.values(holdings) as Holding[];

  // Stats Calculations
  const totalAssets = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    return sum + (fund ? fund.estimatedValue * holding.amount : 0);
  }, 0);

  const dayProfit = holdingsValues.reduce<number>((sum, holding) => {
    const fund = funds.find(f => f.code === holding.fundCode);
    if (!fund) return sum;
    return sum + (holding.amount * (fund.estimatedValue - fund.netValue));
  }, 0);

  const totalReturn = holdingsValues.reduce<number>((sum, holding) => {
      const fund = funds.find(f => f.code === holding.fundCode);
      if (!fund) return sum;
      return sum + ((fund.estimatedValue * holding.amount) - (holding.amount * holding.cost));
  }, 0);

  const filteredFunds = funds.filter(f => 
    f.name.includes(searchTerm) || f.code.includes(searchTerm)
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 font-sans">
      {/* Navbar */}
      <nav className="sticky top-0 z-30 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-gray-200 dark:border-gray-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-blue-600 p-2 rounded-lg">
                <TrendingUp className="w-6 h-6 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600 dark:from-blue-400 dark:to-indigo-400 leading-none">
                    基金智投 AI
                </h1>
                <span className="text-xs text-gray-400 mt-1">实盘估值监控</span>
              </div>
            </div>

            {/* Market Status Indicator */}
            <div className={`hidden md:flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-medium ${marketStatus.color}`}>
                <div className={`w-1.5 h-1.5 rounded-full ${marketStatus.active ? 'bg-green-500 animate-pulse' : 'bg-gray-400'}`}></div>
                <Clock className="w-3 h-3" />
                {marketStatus.text}
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
              {/* Auto Refresh Toggle */}
              <button
                onClick={() => setIsAutoRefresh(!isAutoRefresh)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                  isAutoRefresh 
                    ? 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' 
                    : 'bg-gray-50 text-gray-500 border-gray-200 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-700'
                }`}
                title={isAutoRefresh ? "点击暂停自动刷新" : "点击开启自动刷新"}
              >
                {isAutoRefresh ? <PauseCircle className="w-3.5 h-3.5" /> : <PlayCircle className="w-3.5 h-3.5" />}
                <span className="hidden sm:inline">{isAutoRefresh ? '自动刷新' : '已暂停'}</span>
              </button>

              <div className="hidden sm:block text-xs text-gray-400 text-right">
                  <div>更新: {lastUpdated}</div>
                  <div className="md:hidden text-[10px]">{marketStatus.text}</div>
              </div>
              <button 
                onClick={() => {
                    refreshFunds();
                }}
                disabled={isRefreshing}
                className={`p-2 rounded-full transition-all bg-gray-100 text-gray-500 hover:bg-blue-100 hover:text-blue-600 dark:bg-gray-800 dark:hover:bg-blue-900/30 dark:hover:text-blue-400 ${isRefreshing ? 'animate-spin text-blue-600 bg-blue-50' : ''}`}
                title="刷新数据"
              >
                <RefreshCw className={`w-5 h-5`} />
              </button>
              <div className="h-8 w-8 rounded-full bg-gradient-to-tr from-blue-500 to-purple-500"></div>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Dashboard Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className="absolute right-0 top-0 w-32 h-32 bg-blue-500/10 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <Wallet className="w-5 h-5" />
                    <span className="text-sm font-medium">总资产</span>
                </div>
                <div className="text-3xl font-bold text-gray-900 dark:text-white">
                    {isAppLoading ? (
                         <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `¥${totalAssets.toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                 <div className="text-sm text-gray-400 mt-1">
                    总盈亏: <span className={totalReturn >= 0 ? 'text-red-500' : 'text-green-500'}>{totalReturn >=0 ? '+' : ''}¥{totalReturn.toLocaleString('zh-CN', { maximumFractionDigits: 0 })}</span>
                </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 relative overflow-hidden group">
            <div className={`absolute right-0 top-0 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 ${dayProfit >= 0 ? 'bg-red-500/10' : 'bg-green-500/10'}`}></div>
            <div className="relative z-10">
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
                    <TrendingUp className="w-5 h-5" />
                    <span className="text-sm font-medium">当日预估盈亏</span>
                </div>
                <div className={`text-3xl font-bold ${dayProfit >= 0 ? 'text-red-500' : 'text-green-500'}`}>
                    {isAppLoading ? (
                        <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse"></div>
                    ) : (
                        `${dayProfit >= 0 ? '+' : ''}¥${Math.abs(dayProfit).toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
                    )}
                </div>
                <div className="text-sm text-gray-400 mt-1">
                    基于实时估值计算
                </div>
            </div>
          </div>

          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-2xl p-6 shadow-lg text-white relative overflow-hidden">
             <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
             <div className="relative z-10 h-full flex flex-col justify-between">
                <div>
                    <h3 className="text-lg font-semibold mb-1">AI 市场洞察</h3>
                    <p className="text-indigo-200 text-sm">Gemini 3 实时分析已就绪。</p>
                </div>
                <button className="self-start mt-4 bg-white/20 hover:bg-white/30 backdrop-blur-sm px-4 py-2 rounded-lg text-sm font-medium transition-colors">
                    查看详细报告
                </button>
             </div>
          </div>
        </div>

        {/* Fund List */}
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <h2 className="text-lg font-bold text-gray-900 dark:text-white">自选基金</h2>
            <div className="flex gap-3">
              <div className="relative">
                <Search className="w-5 h-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input 
                  type="text" 
                  placeholder="搜索代码/名称..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none w-full sm:w-64"
                />
              </div>
              <button 
                onClick={() => setIsAddModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
              >
                <Plus className="w-4 h-4" />
                添加
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 dark:bg-gray-900/50 text-xs uppercase tracking-wider text-gray-500">
                  <th className="px-6 py-4 font-medium">基金名称</th>
                  <th className="px-6 py-4 font-medium text-right">估算净值</th>
                  <th className="px-6 py-4 font-medium text-right">估算涨幅</th>
                  <th className="px-6 py-4 font-medium text-right">持有收益 (估算)</th>
                  <th className="px-6 py-4 font-medium text-center">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {isAppLoading ? (
                    // Skeleton Rows for Initial Loading
                    <>
                        <SkeletonRow />
                        <SkeletonRow />
                        <SkeletonRow />
                    </>
                ) : (
                    filteredFunds.map(fund => {
                      const holding = holdings[fund.code];
                      const profit = holding ? holding.amount * (fund.estimatedValue - holding.cost) : 0;
                      const isPositive = fund.growthRate >= 0;
                      const profitIsPositive = profit >= 0;
                      const isError = fund.status === 'error';

                      return (
                        <tr 
                            key={fund.code} 
                            className={`group transition-colors cursor-pointer border-l-4 ${isError ? 'border-l-red-400 bg-red-50/30' : 'border-l-transparent hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}
                            onClick={() => setSelectedFundCode(fund.code)}
                        >
                          <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                                <div>
                                    <div className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                        {fund.name}
                                        {isError && (
                                            <span title="更新失败" className="flex items-center">
                                                <AlertCircle className="w-4 h-4 text-red-500" />
                                            </span>
                                        )}
                                    </div>
                                    <div className="text-xs text-gray-500 font-mono">{fund.code}</div>
                                </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-right font-mono text-gray-700 dark:text-gray-300">
                            {fund.estimatedValue.toFixed(4)}
                          </td>
                          <td className={`px-6 py-4 text-right font-bold font-mono ${isPositive ? 'text-red-500' : 'text-green-500'}`}>
                            {isPositive ? '+' : ''}{fund.growthRate}%
                          </td>
                          <td className={`px-6 py-4 text-right font-medium ${holding ? (profitIsPositive ? 'text-red-500' : 'text-green-500') : 'text-gray-400'}`}>
                            {holding ? `¥${profit.toLocaleString('zh-CN', {maximumFractionDigits: 2})}` : '-'}
                          </td>
                          <td className="px-6 py-4 text-center">
                            <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button 
                                    className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                                    title="查看详情"
                                >
                                    <Eye className="w-4 h-4" />
                                </button>
                                <button 
                                    className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                                    onClick={(e) => handleDeleteClick(e, fund.code)}
                                    title="删除基金"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                )}
              </tbody>
            </table>
          </div>

          {!isAppLoading && filteredFunds.length === 0 && (
            <div className="p-12 text-center flex flex-col items-center justify-center text-gray-400">
                <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-full mb-4">
                    <Search className="w-8 h-8 text-gray-300" />
                </div>
                <p>{funds.length === 0 ? "暂无自选基金，请点击上方“添加”按钮" : "未找到匹配的基金"}</p>
            </div>
          )}
        </div>
      </main>

      <FundDetailModal 
        fund={selectedFund} 
        onClose={() => setSelectedFundCode(null)} 
        holding={selectedFundCode ? holdings[selectedFundCode] : undefined}
        onUpdateHolding={handleUpdateHolding}
        onDelete={() => selectedFundCode && executeDelete(selectedFundCode)}
      />

      {isAddModalOpen && (
        <AddFundModal 
          onClose={() => setIsAddModalOpen(false)}
          onAdd={handleAddFund}
          existingCodes={funds.map(f => f.code)}
          holdings={holdings}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { X, Search, CheckCircle, PieChart, DollarSign, AlertCircle } from 'lucide-react';
import { fetchFundRealtime } from '../services/fundService';
import { Holding } from '../types';

interface AddFundModalProps {
  onClose: () => void;
  onAdd: (code: string, amount: number, cost: number) => Promise<void>;
  existingCodes: string[];
  holdings?: Record<string, Holding>;
}

const AddFundModal: React.FC<AddFundModalProps> = ({ onClose, onAdd, existingCodes, holdings }) => {
  const [code, setCode] = useState('');
  const [amount, setAmount] = useState('');
  const [cost, setCost] = useState(''); // Unit Cost
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [warning, setWarning] = useState(''); // Warning for existing funds
  const [previewName, setPreviewName] = useState('');

  const handleCodeBlur = async () => {
    // 1. Check duplicate
    if (code.length === 6) {
        if (existingCodes.includes(code)) {
            setWarning('该基金已在自选列表中');
            setPreviewName('');
            return;
        } else {
            setWarning('');
        }

        setIsLoading(true);
        setError('');
        try {
            const fund = await fetchFundRealtime(code);
            setPreviewName(fund.name);

            // 2. Auto-fill logic
            if (!cost) {
                // Priority: Historical Cost > Current Net Value
                const historyCost = holdings?.[code]?.cost;
                if (historyCost && historyCost > 0) {
                    setCost(historyCost.toString());
                } else {
                    setCost(fund.netValue.toFixed(4));
                }
            }
        } catch (err) {
            setError('无法获取该基金信息，请检查代码');
            setPreviewName('');
        } finally {
            setIsLoading(false);
        }
    }
  };

  const handleCodeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value.replace(/\D/g, '').slice(0, 6);
      setCode(val);
      setError('');
      if (val.length === 6 && existingCodes.includes(val)) {
          setWarning('该基金已在自选列表中');
      } else {
          setWarning('');
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (code.length < 6) {
      setError('请输入正确的6位基金代码');
      return;
    }

    if (existingCodes.includes(code)) {
      setError('该基金已在您的列表中');
      return;
    }

    setIsLoading(true);
    try {
      const shares = parseFloat(amount) || 0;
      const unitCost = parseFloat(cost) || 0;

      await onAdd(code, shares, unitCost);
      onClose();
    } catch (err) {
      setError('添加失败，请重试');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white dark:bg-gray-800 rounded-2xl w-full max-w-md shadow-2xl scale-100 transform transition-all">
        <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-700">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white">添加自选基金</h3>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          {/* Fund Code Input */}
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              基金代码
            </label>
            <div className="relative">
              <input
                type="text"
                value={code}
                onChange={handleCodeChange}
                onBlur={handleCodeBlur}
                className={`w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-gray-900 border rounded-xl focus:ring-2 focus:outline-none text-lg tracking-widest font-mono ${
                    warning 
                    ? 'border-red-300 focus:ring-red-200 text-red-600' 
                    : 'border-gray-200 dark:border-gray-600 focus:ring-blue-500'
                }`}
                placeholder="000001"
                autoFocus
              />
              <Search className="w-5 h-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
            </div>

            {/* Valid Feedback */}
            {previewName && !warning && (
              <p className="mt-2 text-sm text-green-600 dark:text-green-400 flex items-center gap-1 animate-in fade-in slide-in-from-top-1">
                <CheckCircle className="w-3 h-3" /> 已找到: {previewName}
              </p>
            )}

             {/* Existing Warning */}
             {warning && (
              <p className="mt-2 text-sm text-red-500 flex items-center gap-1 animate-in fade-in slide-in-from-top-1">
                <AlertCircle className="w-3 h-3" /> {warning}
              </p>
            )}

            {/* Error Feedback */}
            {error && <p className="mt-2 text-sm text-red-500">{error}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            {/* Holding Amount */}
            <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  持有份额
                </label>
                <div className="relative">
                  <input
                    type="number"
                    step="0.01"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    className="w-full pl-9 pr-3 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none"
                    placeholder="0"
                  />
                  <PieChart className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                </div>
            </div>

            {/* Unit Cost */}
            <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  持仓成本 (单价)
                </label>
                <div className="relative">
                  <input
                    type="number"
                    step="0.0001"
                    value={cost}
                    onChange={(e) => setCost(e.target.value)}
                    className="w-full pl-9 pr-3 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none"
                    placeholder="单价"
                  />
                  <DollarSign className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                </div>
            </div>
          </div>

          <div className="flex gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2.5 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 rounded-xl font-medium transition-colors"
            >
              取消
            </button>
            <button
              type="submit"
              disabled={code.length !== 6 || isLoading || !!warning}
              className="flex-1 px-4 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-300 disabled:dark:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed text-white rounded-xl font-medium transition-colors shadow-lg shadow-blue-500/30 flex items-center justify-center gap-2"
            >
              {isLoading ? (
                  <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
              ) : (
                  <>
                    <CheckCircle className="w-5 h-5" />
                    确认添加
                  </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

