import { AIAnalysisResult } from '../types';

// 获取 API Key，实际项目中建议通过后端转发或构建时注入
// 格式通常为: "id.secret"
const API_KEY = process.env.ZHIPU_API_KEY || ''; 

export const analyzeFundWithZhipu = async (fundName: string, growthRate: number, tags: string[]): Promise<AIAnalysisResult> => {
  if (!API_KEY) {
    return {
      sentiment: 'neutral',
      analysis: '请配置 ZHIPU_API_KEY 以启用 AI 分析功能。',
    };
  }

  try {
    const prompt = `
      你是一个专业的中国基金市场分析师。请分析名为 "${fundName}" 的基金。
      当前实时涨跌幅为 ${growthRate >= 0 ? '+' : ''}${growthRate.toFixed(2)}%。
      基金标签: ${tags.join(', ')}。

      请基于中国A股市场背景、行业板块轮动逻辑，提供一段简短的市场情绪和基金表现分析。

      要求：
      1. 返回格式必须是纯 JSON。
      2. 包含 'sentiment' 字段 (enum: 'positive', 'neutral', 'negative')。
      3. 包含 'analysis' 字段 (80字以内的中文简评，语气专业客观)。
      4. 不要包含 Markdown 代码块标记。
    `;

    // 使用智谱 AI 的 OpenAI 兼容接口
    const response = await fetch("https://open.bigmodel.cn/api/paas/v4/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${API_KEY}`
      },
      body: JSON.stringify({
        model: "glm-4-flash", // 使用 Flash 模型，速度快且免费/便宜
        messages: [
          {
            role: "system",
            content: "你是一个金融分析助手，只返回 JSON 格式的数据。"
          },
          {
            role: "user",
            content: prompt
          }
        ],
        temperature: 0.7,
        top_p: 0.9,
        max_tokens: 200,
        stream: false
      })
    });

    if (!response.ok) {
        const errData = await response.json();
        console.error('Zhipu API Error:', errData);
        throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    const content = data.choices?.[0]?.message?.content || '{}';

    // 清理可能的 Markdown 标记 (虽然 Prompt 要求不加，但为了稳健)
    const cleanJson = content.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(cleanJson) as AIAnalysisResult;

  } catch (error) {
    console.error('Zhipu analysis failed:', error);
    return {
      sentiment: 'neutral',
      analysis: 'AI分析暂时不可用，可能是网络问题或额度不足。',
    };
  }
};

import React, { useState, useEffect } from 'react';
import { Fund, FundHistoryPoint, AIAnalysisResult, Holding } from '../types';
import FundChart from './FundChart';
import { generateTrendData } from '../services/fundService';
import { analyzeFundWithZhipu } from '../services/zhipuService';
import { X, Sparkles, PieChart, Trash2 } from 'lucide-react';

interface FundDetailModalProps {
  fund: Fund | null;
  onClose: () => void;
  holding?: Holding;
  onUpdateHolding: (amount: number, cost: number) => void;
  onDelete: () => void;
}

const FundDetailModal: React.FC<FundDetailModalProps> = ({ fund, onClose, holding, onUpdateHolding, onDelete }) => {
  const [chartData, setChartData] = useState<FundHistoryPoint[]>([]);
  const [analysis, setAnalysis] = useState<AIAnalysisResult | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [sharesInput, setSharesInput] = useState(holding?.amount.toString() || '0');
  const [costInput, setCostInput] = useState(holding?.cost.toString() || '0');

  useEffect(() => {
    if (fund) {
      setChartData(generateTrendData(fund));
      // Reset state for new fund
      setAnalysis(null);
      setSharesInput(holding?.amount.toString() || '0');
      setCostInput(holding?.cost.toString() || '0');
    }
  }, [fund, holding]);

  if (!fund) return null;

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeFundWithZhipu(fund.name, fund.growthRate, fund.tags);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const handleSaveHolding = () => {
    const amount = parseFloat(sharesInput);
    const cost = parseFloat(costInput);
    if (!isNaN(amount) && !isNaN(cost)) {
      onUpdateHolding(amount, cost);
    }
  };

  const currentHoldingValue = (parseFloat(sharesInput) || 0) * fund.estimatedValue;
  const holdingCostValue = (parseFloat(sharesInput) || 0) * (parseFloat(costInput) || 0);
  const totalReturn = currentHoldingValue - holdingCostValue;
  const returnRate = holdingCostValue > 0 ? (totalReturn / holdingCostValue) * 100 : 0;
