                    <span className="px-2 py-0.5 text-xs font-mono bg-gray-100 dark:bg-gray-800 text-gray-500 rounded">{fund.code}</span>
                </div>
                <div className="flex gap-2 mt-2">
                    {fund.tags && fund.tags.map(tag => (
