                            {fund.estimatedValue.toFixed(4)}
                        </p>
                    </div>
                     <div className="p-4 bg-gray-50 dark:bg-gray-800 rounded-xl">
                        <p className="text-sm text-gray-500 mb-1">估算涨幅</p>
                        <p className={`text-xl font-bold ${isPositive ? 'text-red-500' : 'text-green-500'}`}>
                            {fund.growthRate > 0 ? '+' : ''}{fund.growthRate.toFixed(2)}%
