import { MarketIndex } from '../types';

interface EastmoneyIndexItem {
  f12: string; // Code
  f14: string; // Name
  f2: number;  // Current Value
  f3: number;  // Change Percent
  f4: number;  // Change Amount
}

interface EastmoneyIndexResponse {
  data: {
    diff: EastmoneyIndexItem[];
  };
}

export const fetchMarketIndices = (): Promise<MarketIndex[]> => {
  return new Promise((resolve, reject) => {
    const timestamp = new Date().getTime();
    // Use a unique callback name for each request to prevent race conditions.
    // "Script error." often occurs when the callback function is deleted by a previous request's cleanup
    // before the current request's script executes.
    const callbackName = `market_indices_callback_${timestamp}_${Math.floor(Math.random() * 100000)}`;

    // 1. Setup Callback
    (window as any)[callbackName] = (data: EastmoneyIndexResponse) => {
      try {
        if (data && data.data && data.data.diff) {
          const indices: MarketIndex[] = data.data.diff.map(item => ({
            code: item.f12,
            name: item.f14,
            current: item.f2, // Eastmoney push2 API returns raw numeric values, no division needed
            change: item.f4,
            percent: item.f3
          }));
          resolve(indices);
        } else {
          reject(new Error('Invalid data structure'));
        }
      } catch (error) {
        reject(error);
      } finally {
        cleanup();
      }
    };

    // 2. Prepare Script
    const url = `https://push2.eastmoney.com/api/qt/ulist/get?invt=2&pi=0&pz=10&po=1&np=1&fltt=2&fid=f3&fs=i:1.000001,i:0.399001,i:0.399006&fields=f2,f3,f4,f12,f14&cb=${callbackName}&_=${timestamp}`;
    const scriptId = `market-indices-script-${callbackName}`;

    // Cleanup helper
    const cleanup = () => {
      const s = document.getElementById(scriptId);
      if (s) document.body.removeChild(s);
      delete (window as any)[callbackName];
    };

    const script = document.createElement('script');
    script.src = url;
    script.id = scriptId;
    script.onerror = () => {
      cleanup();
      reject(new Error('Failed to fetch market indices'));
    };

    document.body.appendChild(script);
  });
};

import { AIAnalysisResult } from '../types';

// 获取 API Key，实际项目中建议通过后端转发或构建时注入
// 格式通常为: "id.secret"
const getApiKey = () => {
  // Check if process is defined (Node.js / Bundled env)
  if (typeof process !== 'undefined' && process.env && process.env.ZHIPU_API_KEY) {
    return process.env.ZHIPU_API_KEY;
  }
  return '';
};

const API_KEY = getApiKey();

export const analyzeFundWithZhipu = async (fundName: string, growthRate: number, tags: string[]): Promise<AIAnalysisResult> => {
  if (!API_KEY) {
    return {
      sentiment: 'neutral',
      analysis: '请配置 ZHIPU_API_KEY 以启用 AI 分析功能。',
    };
  }

  try {
    const prompt = `
      你是一个专业的中国基金市场分析师。请分析名为 "${fundName}" 的基金。
      当前实时涨跌幅为 ${growthRate >= 0 ? '+' : ''}${growthRate.toFixed(2)}%。
      基金标签: ${tags.join(', ')}。

      请基于中国A股市场背景、行业板块轮动逻辑，提供一段简短的市场情绪和基金表现分析。

      要求：
      1. 返回格式必须是纯 JSON。
      2. 包含 'sentiment' 字段 (enum: 'positive', 'neutral', 'negative')。
      3. 包含 'analysis' 字段 (80字以内的中文简评，语气专业客观)。
      4. 不要包含 Markdown 代码块标记。
    `;

    // 使用智谱 AI 的 OpenAI 兼容接口
    const response = await fetch("https://open.bigmodel.cn/api/paas/v4/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${API_KEY}`
      },
      body: JSON.stringify({
        model: "glm-4-flash", // 使用 Flash 模型，速度快且免费/便宜
        messages: [
          {
            role: "system",
            content: "你是一个金融分析助手，只返回 JSON 格式的数据。"
          },
          {
            role: "user",
            content: prompt
          }
        ],
        temperature: 0.7,
        top_p: 0.9,
        max_tokens: 200,
        stream: false
      })
    });

    if (!response.ok) {
        const errData = await response.json();
        console.error('Zhipu API Error:', errData);
        throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    const content = data.choices?.[0]?.message?.content || '{}';

    // 清理可能的 Markdown 标记 (虽然 Prompt 要求不加，但为了稳健)
    const cleanJson = content.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(cleanJson) as AIAnalysisResult;

  } catch (error) {
    console.error('Zhipu analysis failed:', error);
    return {
      sentiment: 'neutral',
      analysis: 'AI分析暂时不可用，可能是网络问题或额度不足。',
    };
  }
};

import { MarketIndex } from '../types';

interface EastmoneyStockData {
  f43: number; // Current Price (latest)
  f169: number; // Change Amount
  f170: number; // Change Percent
  f57: string; // Code
  f58: string; // Name
}

interface EastmoneyStockResponse {
  data: EastmoneyStockData | null;
}

const INDICES_CONFIG = [
  { secid: '1.000001', defaultName: '上证指数' },
  { secid: '0.399001', defaultName: '深证成指' },
  { secid: '0.399006', defaultName: '创业板指' }
];

export const fetchMarketIndices = async (): Promise<MarketIndex[]> => {
  const promises = INDICES_CONFIG.map(cfg => fetchSingleIndex(cfg.secid, cfg.defaultName));
  const results = await Promise.all(promises);
  return results.filter((item): item is MarketIndex => item !== null);
};

const fetchSingleIndex = (secid: string, defaultName: string): Promise<MarketIndex | null> => {
  return new Promise((resolve) => {
    const timestamp = new Date().getTime();
    // Unique callback name to avoid race conditions
    const callbackName = `market_idx_${secid.replace('.', '_')}_${timestamp}_${Math.floor(Math.random() * 1000)}`;

    // 1. Setup Callback
    (window as any)[callbackName] = (response: EastmoneyStockResponse) => {
      cleanup(); // Clean up immediately upon receiving data

      if (response && response.data) {
        const { f43, f169, f170, f57, f58 } = response.data;

        // Eastmoney sometimes returns "-" for values before market open or on error
        const current = typeof f43 === 'number' ? f43 : 0;
        const change = typeof f169 === 'number' ? f169 : 0;
        const percent = typeof f170 === 'number' ? f170 : 0;

        resolve({
          code: f57 || secid.split('.')[1],
          name: f58 || defaultName,
          current: current, 
          change: change,
          percent: percent
        });
      } else {
        // Resolve null silently on data error
        resolve(null);
      }
    };

    // 2. Prepare Script
    // Endpoint: stock/get
    // fltt=2: Request float values (not scaled integers)
    // fields: f43(price), f57(code), f58(name), f169(change), f170(percent)
    const url = `https://push2.eastmoney.com/api/qt/stock/get?invt=2&fltt=2&fields=f43,f57,f58,f169,f170&secid=${secid}&cb=${callbackName}&_=${timestamp}`;
    const scriptId = `script-${callbackName}`;

    const cleanup = () => {
      const s = document.getElementById(scriptId);
      if (s) document.body.removeChild(s);
      delete (window as any)[callbackName];
    };

    const script = document.createElement('script');
    script.src = url;
    script.id = scriptId;

    script.onerror = () => {
      cleanup();
      // Resolve null silently on network error
      resolve(null);
    };

    document.body.appendChild(script);
  });
};

import Taro from '@tarojs/taro';
import { Fund, FundHistoryPoint } from '../types';

interface EastmoneyResponse {
  fundcode: string;
  name: string;
  jzrq: string; 
  dwjz: string; 
  gsz: string;  
  gszzl: string; 
  gztime: string; 
}

export const fetchFundRealtime = async (code: string): Promise<Fund> => {
  try {
    const timestamp = new Date().getTime();
    const url = `https://fundgz.1234567.com.cn/js/${code}.js?rt=${timestamp}`;

    // WeChat Mini Program handles CORS differently (whitelisting).
    // We fetch the text script and parse it manually since we can't use JSONP (script injection).
    const response = await Taro.request({
      url: url,
      method: 'GET',
      responseType: 'text',
      dataType: 'text', // Force text response to handle the "jsonpgz(...)" wrapper
    });

    if (response.statusCode !== 200) {
      throw new Error(`Network Error: ${response.statusCode}`);
    }

    const text = response.data as string;

    // Extract JSON from: jsonpgz({"fundcode":"...",...});
    const match = text.match(/jsonpgz\((.*)\)/);

    if (!match || !match[1]) {
        throw new Error('Invalid response format');
    }

    const data: EastmoneyResponse = JSON.parse(match[1]);

    const netValue = parseFloat(data.dwjz || '0');
    const estimatedValue = parseFloat(data.gsz || '0');
    const growthRate = parseFloat(data.gszzl || '0');

    // Guess tags based on name
    const tags = ['混合型'];
    if (data.name.includes('酒')) tags.push('消费');
    if (data.name.includes('医') || data.name.includes('药')) tags.push('医药');
    if (data.name.includes('新能') || data.name.includes('光伏')) tags.push('新能源');
    if (data.name.includes('半导体') || data.name.includes('电子') || data.name.includes('信息')) tags.push('科技');
    if (data.name.includes('蓝筹')) tags.push('蓝筹');
    if (data.name.includes('沪深') || data.name.includes('指数') || data.name.includes('ETF')) {
        tags[0] = '指数型';
    } else if (data.name.includes('债')) {
        tags[0] = '债券型';
    }

    return {
      code: data.fundcode,
      name: data.name,
      netValue,
      estimatedValue: (isNaN(estimatedValue) || estimatedValue === 0) ? netValue : estimatedValue, 
      growthRate: isNaN(growthRate) ? 0 : growthRate,
      updateTime: data.gztime || '--:--',
      tags
    };
  } catch (error) {
    console.warn(`Error fetching fund ${code}:`, error);
    throw error;
  }
};

export const generateTrendData = (fund: Fund): FundHistoryPoint[] => {
    const data: FundHistoryPoint[] = [];
    data.push({ time: '09:30', value: fund.netValue });

    const now = new Date();
    const currentHour = now.getHours();
    const currentMin = now.getMinutes();

    let endTimeStr = `${currentHour.toString().padStart(2, '0')}:${currentMin.toString().padStart(2, '0')}`;

    if (currentHour < 9 || (currentHour === 9 && currentMin < 30)) {
        endTimeStr = '09:30'; 
    } else if (currentHour >= 15) {
        endTimeStr = '15:00';
    }

    if (endTimeStr !== '09:30') {
         data.push({ time: endTimeStr, value: fund.estimatedValue });
    } else {
        data.push({ time: '09:31', value: fund.estimatedValue });
    }

    return data;
};

import Taro from '@tarojs/taro';
import { MarketIndex } from '../types';

interface EastmoneyStockData {
  f43: number; // Current Price
  f169: number; // Change Amount
  f170: number; // Change Percent
  f57: string; // Code
  f58: string; // Name
}

interface EastmoneyStockResponse {
  data: EastmoneyStockData | null;
}

const INDICES_CONFIG = [
  { secid: '1.000001', defaultName: '上证指数' },
  { secid: '0.399001', defaultName: '深证成指' },
  { secid: '0.399006', defaultName: '创业板指' }
];

export const fetchMarketIndices = async (): Promise<MarketIndex[]> => {
  const promises = INDICES_CONFIG.map(cfg => fetchSingleIndex(cfg.secid, cfg.defaultName));
  const results = await Promise.all(promises);
  return results.filter((item): item is MarketIndex => item !== null);
};

const fetchSingleIndex = async (secid: string, defaultName: string): Promise<MarketIndex | null> => {
  try {
    const timestamp = new Date().getTime();
    // Removed callback (cb) parameter to try getting pure JSON if possible, 
    // or we parse the callback string if API insists.
    // Eastmoney stock/get usually supports JSON-like returns but let's stick to the robust parsing.
    const url = `https://push2.eastmoney.com/api/qt/stock/get?invt=2&fltt=2&fields=f43,f57,f58,f169,f170&secid=${secid}&_=${timestamp}`;

    const response = await Taro.request({
      url: url,
      method: 'GET'
    });

    let resultData: EastmoneyStockData | null = null;

    if (response.data && typeof response.data === 'object' && response.data.data) {
        // Direct JSON
        resultData = response.data.data;
    } else if (typeof response.data === 'string') {
        // Handle "callback(...)" case if API returns it
        const match = (response.data as string).match(/\((.*)\)/);
        if (match && match[1]) {
            const parsed = JSON.parse(match[1]);
            resultData = parsed.data;
        }
    }

    if (resultData) {
        const { f43, f169, f170, f57, f58 } = resultData;
        return {
          code: f57 || secid.split('.')[1],
          name: f58 || defaultName,
          current: typeof f43 === 'number' ? f43 : 0,
          change: typeof f169 === 'number' ? f169 : 0,
          percent: typeof f170 === 'number' ? f170 : 0
        };
    }
    return null;
  } catch (error) {
    console.error(`Failed to fetch index ${defaultName}`, error);
    return null;
  }
};

import Taro from '@tarojs/taro';
import { AIAnalysisResult } from '../types';

// In Taro/Mini Program, enviroment variables are usually handled in project.config.json or defineConstants.
// For now, we assume a hardcoded key or passed variable for this demo since process.env is Node-specific.
const API_KEY = process.env.ZHIPU_API_KEY || ''; 

export const analyzeFundWithZhipu = async (fundName: string, growthRate: number, tags: string[]): Promise<AIAnalysisResult> => {
  if (!API_KEY) {
    return {
      sentiment: 'neutral',
      analysis: '未配置 API Key，无法使用 AI 分析。',
    };
  }

  try {
    const prompt = `
      你是一个专业的中国基金市场分析师。请分析名为 "${fundName}" 的基金。
      当前实时涨跌幅为 ${growthRate >= 0 ? '+' : ''}${growthRate.toFixed(2)}%。
      基金标签: ${tags.join(', ')}。

      请基于中国A股市场背景、行业板块轮动逻辑，提供一段简短的市场情绪和基金表现分析。

      要求：
      1. 返回格式必须是纯 JSON。
      2. 包含 'sentiment' 字段 (enum: 'positive', 'neutral', 'negative')。
      3. 包含 'analysis' 字段 (80字以内的中文简评，语气专业客观)。
    `;

    const response = await Taro.request({
      url: "https://open.bigmodel.cn/api/paas/v4/chat/completions",
      method: "POST",
      header: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${API_KEY}`
      },
      data: {
        model: "glm-4-flash",
        messages: [
          { role: "system", content: "你是一个金融分析助手，只返回 JSON 格式的数据。" },
          { role: "user", content: prompt }
        ],
        temperature: 0.7,
        top_p: 0.9,
        max_tokens: 200,
        stream: false
      }
    });

    if (response.statusCode !== 200) {
        throw new Error(`API Error: ${response.statusCode}`);
    }

    const content = response.data?.choices?.[0]?.message?.content || '{}';
    const cleanJson = content.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(cleanJson) as AIAnalysisResult;

  } catch (error) {
    console.error('Zhipu analysis failed:', error);
    return {
      sentiment: 'neutral',
      analysis: 'AI分析暂时不可用，请稍后再试。',
    };
  }
};

