interface AddFundModalProps {
  onClose: () => void;
  onAdd: (code: string, amount: number, cost: number) => Promise<void>;
  existingCodes: string[];
  holdings?: Record<string, Holding>;
}

const AddFundModal: React.FC<AddFundModalProps> = ({ onClose, onAdd, existingCodes, holdings }) => {
  const [code, setCode] = useState('');
  const [amount, setAmount] = useState('');
  const [cost, setCost] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [warning, setWarning] = useState(''); 
  const [previewName, setPreviewName] = useState('');

  const handleCodeBlur = async () => {
    if (code.length === 6) {
        if (existingCodes.includes(code)) {
            setWarning('已在列表中');
            setPreviewName('');
            return;
        } else {
            setWarning('');
        }

        setIsLoading(true);
        setError('');
        try {
            const fund = await fetchFundRealtime(code);
            setPreviewName(fund.name);

            if (!cost) {
                const historyCost = holdings?.[code]?.cost;
                if (historyCost && historyCost > 0) {
                    setCost(historyCost.toString());
                } else {
                    setCost(fund.netValue.toFixed(4));
                }
            }
        } catch (err) {
            setError('无效代码');
            setPreviewName('');
        } finally {
            setIsLoading(false);
        }
    }
  };

  const handleCodeChange = (e) => {
      const val = e.detail.value.replace(/\D/g, '').slice(0, 6);
      setCode(val);
      setError('');
  };

  const handleSubmit = async () => {
    setError('');

    if (code.length < 6) {
      setError('请输入6位代码');
      return;
    }

    if (existingCodes.includes(code)) {
      setError('已存在');
      return;
    }

    setIsLoading(true);
    try {
      const shares = parseFloat(amount) || 0;
      const unitCost = parseFloat(cost) || 0;

      await onAdd(code, shares, unitCost);
      onClose();
    } catch (err) {
      setError('添加失败');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <View className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60">
      <View className="bg-white dark:bg-gray-800 rounded-2xl w-full max-w-md shadow-2xl">
        <View className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-700">
          <Text className="text-lg font-bold text-gray-900 dark:text-white">添加基金</Text>
          <Button onClick={onClose} className="p-2 text-gray-500 bg-transparent text-xs" size="mini">关闭</Button>
        </View>

        <View className="p-6 space-y-5">
          <View>
            <Text className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              基金代码
            </Text>
            <Input
                type="number"
                value={code}
                onInput={handleCodeChange}
                onBlur={handleCodeBlur}
                className="w-full pl-4 pr-4 py-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-xl h-12"
                placeholder="000001"
            />

            {previewName && !warning && (
              <Text className="mt-2 text-sm text-green-600 block">
                 已找到: {previewName}
              </Text>
            )}

             {warning && (
              <Text className="mt-2 text-sm text-red-500 block">
                 {warning}
              </Text>
            )}

            {error && <Text className="mt-2 text-sm text-red-500 block">{error}</Text>}
          </View>

          <View className="flex gap-4">
            <View className="flex-1">
                <Text className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  持有份额
                </Text>
                <Input
                    type="digit"
                    value={amount}
                    onInput={(e) => setAmount(e.detail.value)}
                    className="w-full pl-4 pr-3 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-xl h-10"
                    placeholder="0"
                  />
            </View>

            <View className="flex-1">
                <Text className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  成本
                </Text>
                <Input
                    type="digit"
                    value={cost}
                    onInput={(e) => setCost(e.detail.value)}
                    className="w-full pl-4 pr-3 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded-xl h-10"
                    placeholder="单价"
                  />
            </View>
          </View>

          <View className="flex gap-3 pt-2">
            <Button
              onClick={onClose}
              className="flex-1 bg-gray-100 text-gray-700 rounded-xl text-sm"
            >
              取消
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={code.length !== 6 || isLoading || !!warning}
              className="flex-1 bg-blue-600 text-white rounded-xl text-sm"
            >
              {isLoading ? '...' : '确认添加'}
            </Button>
          </View>
        </View>
      </View>
    </View>
  );
};

