  const [isAutoRefresh, setIsAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [lastUpdated, setLastUpdated] = useState<string>('');
  const [marketStatus, setMarketStatus] = useState(getMarketStatus());

  const [sortField, setSortField] = useState<SortField | null>(null);
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');
  const [isRefreshing, setIsRefreshing] = useState(false);

  const fundsRef = useRef<Fund[]>([]);

  useEffect(() => {
    fundsRef.current = funds;
  }, [funds]);

  // Initial Load (Taro way)
  useLoad(() => {
      init();
  });

  const init = async () => {
      const savedCodesStr = Taro.getStorageSync('fund_codes');
      const savedHoldingsStr = Taro.getStorageSync('fund_holdings');

      let codesToFetch: string[] = [];
      let initialHoldings = {};

      if (savedHoldingsStr) {
          try {
              initialHoldings = JSON.parse(savedHoldingsStr);
              setHoldings(initialHoldings);
          } catch (e) {}
      }

      if (savedCodesStr) {
          try {
              const parsed = JSON.parse(savedCodesStr);
              if (Array.isArray(parsed)) codesToFetch = parsed;
          } catch (e) {}
      } 

      await Promise.all([
          codesToFetch.length > 0 ? refreshFunds(codesToFetch, true) : setFunds([]),
          refreshIndices()
      ]);
  };

  useEffect(() => {
      const codes = funds.map(f => f.code);
      Taro.setStorageSync('fund_codes', JSON.stringify(codes));
  }, [funds]);

