                        {idx.percent >= 0 ? '↑' : '↓'}{idx.percent.toFixed(2)}%
                    </Text>
                </View>
            ))}
          </View>
      </ScrollView>

      {/* Main Content */}
      <View className="p-4 space-y-4">
