            </Text>
          </View>

          <View className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm relative overflow-hidden">
             <Text className="text-xs text-gray-500 block mb-1">当日盈亏</Text>
             <Text className={`text-xl font-bold ${dayProfit >= 0 ? 'text-red-500' : 'text-green-500'}`}>
                {dayProfit >= 0 ? '+' : ''}¥{Math.abs(dayProfit).toLocaleString('zh-CN', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
            </Text>
          </View>
        </View>

        {/* Action Bar */}
        <View className="flex gap-2">
            <Input 
