                <Text className="w-20 text-right" onClick={() => handleSort('growthRate')}>涨幅</Text>
            </View>

            {sortedFunds.map(fund => {
                const holding = holdings[fund.code];
                const profit = holding ? holding.amount * (fund.estimatedValue - holding.cost) : 0;
                const isPositive = fund.growthRate >= 0;

                return (
                <View 
                    key={fund.code} 
                    className="flex p-3 border-b border-gray-100 items-center active:bg-gray-50"
