                        <Text className="text-sm font-mono block">{fund.estimatedValue.toFixed(4)}</Text>
                    </View>
                    <View className="w-20 text-right">
                        <Text className={`text-sm font-bold ${isPositive ? 'text-red-500' : 'text-green-500'}`}>
