                        </Text>
                    </View>
                </View>
                );
            })}
             {sortedFunds.length === 0 && (
                 <View className="p-8 text-center text-gray-400 text-sm">暂无数据</View>
             )}
        </View>
      </View>

      <FundDetailModal 
        fund={selectedFund} 
