        onUpdateHolding={handleUpdateHolding}
        onDelete={() => selectedFund && deleteFund(selectedFund.code)}
      />

      {isAddModalOpen && (
        <AddFundModal 
          onClose={() => setIsAddModalOpen(false)}
          onAdd={handleAddFund}
          existingCodes={funds.map(f => f.code)}
          holdings={holdings}
        />
      )}
    </View>
  );
}

