const getMarketStatus = () => {
  const now = new Date();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const time = hour * 60 + minute;

  if (day === 0 || day === 6) return { text: '休市', color: 'text-gray-500' };
  if (time >= 9 * 60 + 15 && time < 9 * 60 + 30) return { text: '盘前', color: 'text-orange-600' };
  if (time >= 9 * 60 + 30 && time < 11 * 60 + 30) return { text: '交易中', color: 'text-green-600', active: true };
  if (time >= 11 * 60 + 30 && time < 13 * 60) return { text: '午休', color: 'text-gray-600' };
  if (time >= 13 * 60 && time < 15 * 60) return { text: '交易中', color: 'text-green-600', active: true };
  return { text: '收盘', color: 'text-gray-500' };
};

